    fn doc_list_window(&mut self, ctx: &egui::Context) {
        if !self.show_doc_list {
            return;
        }
        let mut open = self.show_doc_list;
        let mut switch_to = None;
        let mut close = false;
        egui::Window::new("Document List")
            .open(&mut open)
            .default_width(420.0)
            .show(ctx, |ui| {
                egui::ScrollArea::vertical()
                    .max_height(320.0)
                    .show(ui, |ui| {
                        for i in 0..self.state.tabs.len() {
                            let Some(doc) = self.state.tabs.get(i) else {
                                continue;
                            };
                            let mut label = doc.title.clone();
                            if doc.dirty {
                                label.push('*');
                            }
                            if ui
                                .selectable_label(i == self.state.tabs.active_index(), label)
                                .clicked()
                            {
                                switch_to = Some(i);
                            }
                        }
                    });
                if ui.button("Close").clicked() {
                    close = true;
                }
            });
        if let Some(i) = switch_to {
            self.state.switch_tab(i);
            close = true;
        }
        self.show_doc_list = open && !close;
    }

    fn doc_map_window(&mut self, ctx: &egui::Context) {
        if !self.show_doc_map {
            return;
        }
        let map_tab = self.focused_edit_tab();
        let secondary = self.dual_view && self.focused_pane == EditorPane::Secondary;
        let scroll_now = if secondary {
            self.scroll_line_other
        } else {
            self.scroll_line
        };
        let (find_match_total, find_match_hits) = self.state.find_match_line_hits_for_tab(map_tab);
        let (
            line_count,
            sample_n,
            strips,
            hunk_ticks,
            bookmark_ticks,
            ch_unsaved_ticks,
            ch_saved_ticks,
            fold_ticks,
            folded_fold_ticks,
            hide_gaps,
            sel_ranges,
            caret_line,
            multi_caret_ticks,
            compare_active,
            max_scroll,
        ) = {
            let Some(doc) = self.state.tabs.get(map_tab) else {
                return;
            };
            let line_count = doc.buffer.line_count().max(1);
            let max_scroll = (line_count.saturating_sub(1) as f32).max(0.0);
            let caret_line = doc.buffer.char_to_line(doc.buffer.caret());
            let mut sel_ranges: Vec<(usize, usize)> = Vec::new();
            if let Some((s, e)) = doc.buffer.selection() {
                if let Some(span) =
                    crate::diff::doc_map_char_range_lines(s, e, |c| doc.buffer.char_to_line(c))
                {
                    sel_ranges.push(span);
                }
            }
            let mut multi_caret_ticks: Vec<usize> = Vec::new();
            if doc.multi_sels.len() >= 2 {
                for &(s, e) in &doc.multi_sels {
                    let lo = s.min(e);
                    let hi = s.max(e);
                    if lo == hi {
                        multi_caret_ticks.push(doc.buffer.char_to_line(lo));
                    } else if let Some(span) = crate::diff::doc_map_char_range_lines(lo, hi, |c| {
                        doc.buffer.char_to_line(c)
                    }) {
                        sel_ranges.push(span);
                    }
                }
            }
            crate::diff::doc_map_merge_line_ranges(&mut sel_ranges);
            multi_caret_ticks.sort_unstable();
            multi_caret_ticks.dedup();
            let bookmark_ticks: Vec<usize> = doc.bookmarks.iter().copied().collect();
            let ch_unsaved_ticks: Vec<usize> = doc.changed_unsaved.iter().copied().collect();
            let ch_saved_ticks: Vec<usize> = doc
                .changed_saved
                .iter()
                .copied()
                .filter(|l| !doc.changed_unsaved.contains(l))
                .collect();
            let fold_regions =
                crate::fold::compute_fold_regions(doc.language.as_str(), &doc.buffer);
            let mut fold_ticks: Vec<usize> = fold_regions.iter().map(|r| r.header).collect();
            fold_ticks.sort_unstable();
            fold_ticks.dedup();
            let folded_fold_ticks = crate::fold::folded_headers(&doc.hidden_lines, &fold_regions);
            let compare_tags = if self.compare_on {
                if map_tab == self.compare_left_tab {
                    Some(self.compare_left_tags.as_slice())
                } else if map_tab == self.compare_right_tab {
                    Some(self.compare_right_tags.as_slice())
                } else {
                    None
                }
            } else {
                None
            };
            let compare_active = compare_tags.is_some();
            let hunk_ticks = compare_tags
                .map(crate::diff::hunk_starts)
                .unwrap_or_default();
            let hide_gaps = if compare_active && self.state.settings.compare_hide_equal {
                let left_pane = map_tab == self.compare_left_tab;
                let (tags, revealed) = if left_pane {
                    (
                        self.compare_left_tags.as_slice(),
                        &self.compare_hide_revealed_left,
                    )
                } else {
                    (
                        self.compare_right_tags.as_slice(),
                        &self.compare_hide_revealed_right,
                    )
                };
                let visible = visible_lines_with_compare_hide(
                    line_count,
                    &doc.hidden_lines,
                    true,
                    true,
                    tags,
                    revealed,
                    self.state.settings.compare_hide_equal_context_lines(),
                );
                crate::diff::list_compare_hide_gaps(&visible)
            } else {
                Vec::new()
            };
            let sample_n = 128.min(line_count);
            let mut strips = Vec::with_capacity(sample_n);
            for i in 0..sample_n {
                let line_idx = i * line_count / sample_n;
                let raw = doc.buffer.line(line_idx);
                let dens = (raw.trim_end_matches(['\n', '\r']).chars().count() as f32 / 80.0)
                    .clamp(0.05, 1.0);
                let color = compare_tags
                    .and_then(|tags| tags.get(line_idx).copied())
                    .and_then(crate::diff::line_kind_map_color)
                    .unwrap_or_else(|| {
                        let g = (40.0 + dens * 140.0) as u8;
                        Color32::from_rgb(g, g, g.saturating_add(8))
                    });
                strips.push(color);
            }
            (
                line_count,
                sample_n,
                strips,
                hunk_ticks,
                bookmark_ticks,
                ch_unsaved_ticks,
                ch_saved_ticks,
                fold_ticks,
                folded_fold_ticks,
                hide_gaps,
                sel_ranges,
                caret_line,
                multi_caret_ticks,
                compare_active,
                max_scroll,
            )
        };
        let mut open = self.show_doc_map;
        let mut jump_line: Option<f32> = None;
        // Click (not drag) while Compare tags apply: park/select hunk like a gutter click.
        let mut compare_click_line: Option<usize> = None;
        // Click on a hide-equal ···N band: park like Alt+F7 family (not expand).
        let mut hide_gap_click: Option<(usize, usize)> = None;
        // Click near a bookmark tick: park caret on that bookmark line.
        let mut bookmark_click: Option<usize> = None;
        // Click near a fold-header tick: park caret and toggle that fold.
        let mut fold_click: Option<usize> = None;
        // Click near a find-match tick: select that match span.
        let mut find_click: Option<(usize, usize, usize)> = None;
        // Click near a change-history tick: park caret on that changed line.
        let mut ch_click: Option<(usize, bool)> = None;
        // Click near caret / multi-caret tick: park on that caret line.
        let mut caret_click: Option<usize> = None;
        let find_tick_lines: Vec<usize> = find_match_hits.iter().map(|&(l, _, _)| l).collect();
        let mut caret_tick_marks: Vec<usize> = Vec::with_capacity(1 + multi_caret_ticks.len());
        caret_tick_marks.push(caret_line);
        caret_tick_marks.extend_from_slice(&multi_caret_ticks);
        caret_tick_marks.sort_unstable();
        caret_tick_marks.dedup();
        egui::Window::new("Document Map")
            .open(&mut open)
            .default_width(72.0)
            .default_height(360.0)
            .resizable(true)
            .show(ctx, |ui| {
                let mut label = format!("{line_count} lines");
                if compare_active {
                    label.push_str(" · compare");
                    if !hide_gaps.is_empty() {
                        label.push_str(&format!(
                            " · {} gap{}",
                            hide_gaps.len(),
                            if hide_gaps.len() == 1 { "" } else { "s" }
                        ));
                    }
                }
                if find_match_total > 0 {
                    label.push_str(&format!(
                        " · {find_match_total} match{}",
                        if find_match_total == 1 { "" } else { "es" }
                    ));
                }
                if !bookmark_ticks.is_empty() {
                    label.push_str(&format!(
                        " · {} bookmark{}",
                        bookmark_ticks.len(),
                        if bookmark_ticks.len() == 1 { "" } else { "s" }
                    ));
                }
                if !fold_ticks.is_empty() {
                    let folded_n = folded_fold_ticks.len();
                    if folded_n > 0 {
                        label.push_str(&format!(
                            " · {} fold{} ({} folded)",
                            fold_ticks.len(),
                            if fold_ticks.len() == 1 { "" } else { "s" },
                            folded_n
                        ));
                    } else {
                        label.push_str(&format!(
                            " · {} fold{}",
                            fold_ticks.len(),
                            if fold_ticks.len() == 1 { "" } else { "s" }
                        ));
                    }
                }
                let ch_n = ch_unsaved_ticks.len() + ch_saved_ticks.len();
                if ch_n > 0 {
                    label.push_str(&format!(
                        " · {ch_n} change{}",
                        if ch_n == 1 { "" } else { "s" }
                    ));
                }
                if !sel_ranges.is_empty() {
                    label.push_str(" · sel");
                }
                if multi_caret_ticks.len() >= 2 {
                    label.push_str(&format!(" · {} carets", multi_caret_ticks.len()));
                }
                let page_rows = if secondary {
                    self.doc_map_page_rows_other
                } else {
                    self.doc_map_page_rows
                };
                if page_rows > 0 && page_rows < line_count {
                    label.push_str(&format!(" · view {page_rows}"));
                }
                ui.label(label);
                let (resp, painter) = ui.allocate_painter(
                    Vec2::new(
                        ui.available_width().max(40.0),
                        ui.available_height().max(120.0),
                    ),
                    Sense::click_and_drag(),
                );
                let rect = resp.rect;
                painter.rect_filled(rect, 0.0, Color32::from_rgb(28, 28, 32));
                for (i, color) in strips.iter().enumerate() {
                    let y0 = rect.top() + (i as f32 / sample_n as f32) * rect.height();
                    let y1 = rect.top() + ((i + 1) as f32 / sample_n as f32) * rect.height();
                    painter.rect_filled(
                        Rect::from_min_max(Pos2::new(rect.left(), y0), Pos2::new(rect.right(), y1)),
                        0.0,
                        *color,
                    );
                }
                // Selection wash (soft blue) so selected spans read on the map.
                if max_scroll > 0.0 {
                    let sel_fill = Color32::from_rgba_unmultiplied(90, 150, 230, 85);
                    for &(a, b) in &sel_ranges {
                        let y0 =
                            rect.top() + ((a as f32 / max_scroll).clamp(0.0, 1.0) * rect.height());
                        let y1 = rect.top()
                            + (((b as f32 + 0.5) / max_scroll).clamp(0.0, 1.0) * rect.height());
                        let top = y0.min(y1);
                        let h = (y1 - y0).abs().max(2.0);
                        painter.rect_filled(
                            Rect::from_min_size(
                                Pos2::new(rect.left(), top),
                                Vec2::new(rect.width(), h),
                            ),
                            0.0,
                            sel_fill,
                        );
                    }
                }
                // Hide-equal collapsed Equal runs (···N) as muted bands while Hide Unchanged is on.
                if max_scroll > 0.0 {
                    let gap_fill = Color32::from_rgba_unmultiplied(70, 110, 160, 90);
                    for &(a, b) in &hide_gaps {
                        let y0 =
                            rect.top() + ((a as f32 / max_scroll).clamp(0.0, 1.0) * rect.height());
                        let y1 = rect.top()
                            + (((b as f32 + 0.5) / max_scroll).clamp(0.0, 1.0) * rect.height());
                        let top = y0.min(y1);
                        let h = (y1 - y0).abs().max(2.0);
                        painter.rect_filled(
                            Rect::from_min_size(
                                Pos2::new(rect.left(), top),
                                Vec2::new(rect.width(), h),
                            ),
                            0.0,
                            gap_fill,
                        );
                    }
                }
                // Tick marks at change-hunk starts (Compare) so clusters read at a glance.
                if max_scroll > 0.0 {
                    let tick = Color32::from_rgb(230, 200, 90);
                    for &line_idx in &hunk_ticks {
                        let frac = (line_idx as f32 / max_scroll).clamp(0.0, 1.0);
                        let y = rect.top() + frac * rect.height();
                        painter.rect_filled(
                            Rect::from_min_size(
                                Pos2::new(rect.left(), y - 0.75),
                                Vec2::new(rect.width(), 1.5),
                            ),
                            0.0,
                            tick,
                        );
                    }
                }
                // Find-match ticks (magenta, full width) when Find query has hits.
                if max_scroll > 0.0 {
                    let tick = Color32::from_rgb(210, 90, 200);
                    for &(line_idx, _, _) in &find_match_hits {
                        let frac = (line_idx as f32 / max_scroll).clamp(0.0, 1.0);
                        let y = rect.top() + frac * rect.height();
                        painter.rect_filled(
                            Rect::from_min_size(
                                Pos2::new(rect.left(), y - 0.75),
                                Vec2::new(rect.width(), 1.5),
                            ),
                            0.0,
                            tick,
                        );
                    }
                }
                // Bookmark ticks (cyan, left half) — same hue as the gutter bookmark mark.
                if max_scroll > 0.0 {
                    let tick = Color32::from_rgb(80, 180, 220);
                    let w = (rect.width() * 0.45).max(3.0);
                    for &line_idx in &bookmark_ticks {
                        let frac = (line_idx as f32 / max_scroll).clamp(0.0, 1.0);
                        let y = rect.top() + frac * rect.height();
                        painter.rect_filled(
                            Rect::from_min_size(Pos2::new(rect.left(), y - 1.0), Vec2::new(w, 2.0)),
                            0.0,
                            tick,
                        );
                    }
                }
                // Fold-header ticks (slate, left quarter). Brighter when that region is folded.
                if max_scroll > 0.0 {
                    let open_tick = Color32::from_rgb(100, 140, 190);
                    let folded_tick = Color32::from_rgb(170, 200, 235);
                    let w = (rect.width() * 0.28).max(2.5);
                    for &line_idx in &fold_ticks {
                        let frac = (line_idx as f32 / max_scroll).clamp(0.0, 1.0);
                        let y = rect.top() + frac * rect.height();
                        let color = if folded_fold_ticks.binary_search(&line_idx).is_ok() {
                            folded_tick
                        } else {
                            open_tick
                        };
                        painter.rect_filled(
                            Rect::from_min_size(Pos2::new(rect.left(), y - 1.0), Vec2::new(w, 2.0)),
                            0.0,
                            color,
                        );
                    }
                }
                // Change-history ticks (right half): amber unsaved, green saved.
                if max_scroll > 0.0 {
                    let w = (rect.width() * 0.45).max(3.0);
                    let x = rect.right() - w;
                    let paint_ch = |line_idx: usize, color: Color32| {
                        let frac = (line_idx as f32 / max_scroll).clamp(0.0, 1.0);
                        let y = rect.top() + frac * rect.height();
                        painter.rect_filled(
                            Rect::from_min_size(Pos2::new(x, y - 1.0), Vec2::new(w, 2.0)),
                            0.0,
                            color,
                        );
                    };
                    for &line_idx in &ch_saved_ticks {
                        paint_ch(line_idx, change_history_saved_color());
                    }
                    for &line_idx in &ch_unsaved_ticks {
                        paint_ch(line_idx, change_history_unsaved_color());
                    }
                }
                // Multi-caret ticks (orange, center third) when column / multi-select is active.
                if max_scroll > 0.0 {
                    let tick = Color32::from_rgb(240, 160, 70);
                    let w = (rect.width() * 0.34).max(3.0);
                    let x = rect.left() + (rect.width() - w) * 0.5;
                    for &line_idx in &multi_caret_ticks {
                        let frac = (line_idx as f32 / max_scroll).clamp(0.0, 1.0);
                        let y = rect.top() + frac * rect.height();
                        painter.rect_filled(
                            Rect::from_min_size(Pos2::new(x, y - 1.0), Vec2::new(w, 2.0)),
                            0.0,
                            tick,
                        );
                    }
                }
                // Primary caret tick (white, full width) — where the focused caret sits.
                if max_scroll > 0.0 {
                    let tick = Color32::from_rgb(245, 245, 250);
                    let frac = (caret_line as f32 / max_scroll).clamp(0.0, 1.0);
                    let y = rect.top() + frac * rect.height();
                    painter.rect_filled(
                        Rect::from_min_size(
                            Pos2::new(rect.left(), y - 0.75),
                            Vec2::new(rect.width(), 1.5),
                        ),
                        0.0,
                        tick,
                    );
                }
                // Viewport band sized to the editor page (not a fixed ~8% mark).
                if let Some((y_off, mark_h)) = crate::diff::doc_map_viewport_band(
                    scroll_now,
                    max_scroll,
                    page_rows,
                    line_count,
                    rect.height(),
                ) {
                    let mark = Rect::from_min_size(
                        Pos2::new(rect.left() + 1.0, rect.top() + y_off),
                        Vec2::new(rect.width() - 2.0, mark_h),
                    );
                    painter.rect_filled(
                        mark,
                        0.0,
                        Color32::from_rgba_unmultiplied(80, 180, 140, 40),
                    );
                    painter.rect_stroke(
                        mark,
                        0.0,
                        egui::Stroke::new(1.5_f32, Color32::from_rgb(80, 180, 140)),
                        egui::StrokeKind::Outside,
                    );
                }
                if let Some(pos) = resp.interact_pointer_pos() {
                    if resp.clicked() || resp.dragged() {
                        let t = ((pos.y - rect.top()) / rect.height()).clamp(0.0, 1.0);
                        jump_line = Some(t * max_scroll);
                    }
                    if resp.clicked() {
                        let t = ((pos.y - rect.top()) / rect.height()).clamp(0.0, 1.0);
                        let line_idx = (t * max_scroll).round() as usize;
                        let line_idx = line_idx.min(line_count.saturating_sub(1));
                        let snap = ((max_scroll / 64.0).ceil() as usize).max(1);
                        let nearest_ch = || {
                            let mut marks =
                                Vec::with_capacity(ch_unsaved_ticks.len() + ch_saved_ticks.len());
                            marks.extend_from_slice(&ch_unsaved_ticks);
                            marks.extend_from_slice(&ch_saved_ticks);
                            crate::diff::doc_map_nearest_mark(line_idx, &marks, snap).map(|m| {
                                let saved =
                                    ch_saved_ticks.contains(&m) && !ch_unsaved_ticks.contains(&m);
                                (m, saved)
                            })
                        };
                        let nearest_find = || {
                            crate::diff::doc_map_nearest_mark(line_idx, &find_tick_lines, snap)
                                .and_then(|line| {
                                    find_match_hits.iter().copied().find(|(l, _, _)| *l == line)
                                })
                        };
                        let nearest_fold =
                            || crate::diff::doc_map_nearest_mark(line_idx, &fold_ticks, snap);
                        let nearest_caret =
                            || crate::diff::doc_map_nearest_mark(line_idx, &caret_tick_marks, snap);
                        if compare_active {
                            if let Some(gap) =
                                crate::diff::doc_map_compare_hide_gap_at(line_idx, &hide_gaps)
                            {
                                hide_gap_click = Some(gap);
                            } else if let Some(bm) =
                                crate::diff::doc_map_nearest_mark(line_idx, &bookmark_ticks, snap)
                            {
                                bookmark_click = Some(bm);
                            } else if let Some(fh) = nearest_fold() {
                                fold_click = Some(fh);
                            } else if let Some(hit) = nearest_find() {
                                find_click = Some(hit);
                            } else if let Some(ch) = nearest_ch() {
                                ch_click = Some(ch);
                            } else if let Some(cl) = nearest_caret() {
                                caret_click = Some(cl);
                            } else {
                                compare_click_line = Some(line_idx);
                            }
                        } else if let Some(bm) =
                            crate::diff::doc_map_nearest_mark(line_idx, &bookmark_ticks, snap)
                        {
                            bookmark_click = Some(bm);
                        } else if let Some(fh) = nearest_fold() {
                            fold_click = Some(fh);
                        } else if let Some(hit) = nearest_find() {
                            find_click = Some(hit);
                        } else if let Some(ch) = nearest_ch() {
                            ch_click = Some(ch);
                        } else if let Some(cl) = nearest_caret() {
                            caret_click = Some(cl);
                        }
                    }
                }
            });
        if let Some(gap) = hide_gap_click {
            let left_pane = map_tab == self.compare_left_tab;
            let park = crate::diff::compare_hide_gap_park_line(gap);
            let n = gap.1 - gap.0 + 1;
            let (ord, total) =
                crate::diff::compare_hide_gap_ordinal(&hide_gaps, gap).unwrap_or((1, 1));
            if let Some(doc) = self.state.tabs.get_mut(map_tab) {
                let at = doc
                    .buffer
                    .line_to_char(park.min(doc.buffer.line_count().saturating_sub(1)));
                doc.buffer.set_caret(at);
            }
            if secondary {
                self.follow_caret_other = true;
                if self.sync_scroll_v {
                    self.follow_caret = true;
                }
            } else {
                self.follow_caret = true;
                if self.sync_scroll_v {
                    self.follow_caret_other = true;
                }
            }
            self.sync_compare_other_to_equal_line(left_pane, park);
            let counts =
                compare_pair_counts_from_tags(&self.compare_left_tags, &self.compare_right_tags);
            self.state.status = compare_hide_gap_nav_status("Map", n, ord, total, &counts, false);
        } else if let Some(line_idx) = bookmark_click {
            if let Some(doc) = self.state.tabs.get_mut(map_tab) {
                let at = doc
                    .buffer
                    .line_to_char(line_idx.min(doc.buffer.line_count().saturating_sub(1)));
                doc.buffer.set_caret(at);
            }
            if secondary {
                self.follow_caret_other = true;
                if self.sync_scroll_v {
                    self.follow_caret = true;
                }
            } else {
                self.follow_caret = true;
                if self.sync_scroll_v {
                    self.follow_caret_other = true;
                }
            }
            if compare_active {
                // Parks partner + selects hunk (or Equal partner); sets Compare status.
                self.sync_compare_other_to_caret_hunk(map_tab == self.compare_left_tab);
            } else {
                self.state.status = format!("Document Map → bookmark line {}", line_idx + 1);
            }
        } else if let Some(line_idx) = fold_click {
            if let Some(doc) = self.state.tabs.get(map_tab) {
                let lang = doc.language.clone();
                let regions = crate::fold::compute_fold_regions(lang.as_str(), &doc.buffer);
                if let Some(region) = crate::fold::region_at_header(&regions, line_idx) {
                    if let Some(doc) = self.state.tabs.get_mut(map_tab) {
                        let was = crate::fold::is_folded(&doc.hidden_lines, &region);
                        crate::fold::toggle_region(&mut doc.hidden_lines, &region);
                        let at = doc
                            .buffer
                            .line_to_char(line_idx.min(doc.buffer.line_count().saturating_sub(1)));
                        doc.buffer.set_caret(at);
                        let n = region.end - region.header;
                        if !compare_active {
                            self.state.status = if was {
                                format!(
                                    "Document Map → unfolded {n} line{} at {}",
                                    if n == 1 { "" } else { "s" },
                                    line_idx + 1
                                )
                            } else {
                                format!(
                                    "Document Map → folded {n} line{} at {}",
                                    if n == 1 { "" } else { "s" },
                                    line_idx + 1
                                )
                            };
                        }
                    }
                } else if let Some(doc) = self.state.tabs.get_mut(map_tab) {
                    let at = doc
                        .buffer
                        .line_to_char(line_idx.min(doc.buffer.line_count().saturating_sub(1)));
                    doc.buffer.set_caret(at);
                    if !compare_active {
                        self.state.status =
                            format!("Document Map → fold header line {}", line_idx + 1);
                    }
                }
            }
            if secondary {
                self.follow_caret_other = true;
                if self.sync_scroll_v {
                    self.follow_caret = true;
                }
            } else {
                self.follow_caret = true;
                if self.sync_scroll_v {
                    self.follow_caret_other = true;
                }
            }
            if compare_active {
                // Parks partner after fold toggle; sets Compare status.
                self.sync_compare_other_to_caret_hunk(map_tab == self.compare_left_tab);
            }
        } else if let Some((line_idx, start, end)) = find_click {
            if let Some(doc) = self.state.tabs.get_mut(map_tab) {
                doc.buffer.set_selection(start, end);
            }
            if secondary {
                self.follow_caret_other = true;
                if self.sync_scroll_v {
                    self.follow_caret = true;
                }
            } else {
                self.follow_caret = true;
                if self.sync_scroll_v {
                    self.follow_caret_other = true;
                }
            }
            if compare_active {
                // Parks partner + selects hunk (or Equal partner); sets Compare status.
                self.sync_compare_other_to_caret_hunk(map_tab == self.compare_left_tab);
            } else {
                self.state.status = format!(
                    "Document Map → find line {} · {find_match_total} match{}",
                    line_idx + 1,
                    if find_match_total == 1 { "" } else { "es" }
                );
            }
        } else if let Some((line_idx, saved)) = ch_click {
            if let Some(doc) = self.state.tabs.get_mut(map_tab) {
                let at = doc
                    .buffer
                    .line_to_char(line_idx.min(doc.buffer.line_count().saturating_sub(1)));
                doc.buffer.set_caret(at);
            }
            if secondary {
                self.follow_caret_other = true;
                if self.sync_scroll_v {
                    self.follow_caret = true;
                }
            } else {
                self.follow_caret = true;
                if self.sync_scroll_v {
                    self.follow_caret_other = true;
                }
            }
            if compare_active {
                // Parks partner + selects hunk (or Equal partner); sets Compare status.
                self.sync_compare_other_to_caret_hunk(map_tab == self.compare_left_tab);
            } else {
                let kind = if saved { "saved" } else { "unsaved" };
                self.state.status = format!(
                    "Document Map → change history line {} ({kind})",
                    line_idx + 1
                );
            }
        } else if let Some(line_idx) = caret_click {
            if let Some(doc) = self.state.tabs.get_mut(map_tab) {
                let at = doc
                    .buffer
                    .line_to_char(line_idx.min(doc.buffer.line_count().saturating_sub(1)));
                doc.buffer.set_caret(at);
            }
            if secondary {
                self.follow_caret_other = true;
                if self.sync_scroll_v {
                    self.follow_caret = true;
                }
            } else {
                self.follow_caret = true;
                if self.sync_scroll_v {
                    self.follow_caret_other = true;
                }
            }
            if compare_active {
                // Parks partner + selects hunk (or Equal partner); sets Compare status.
                self.sync_compare_other_to_caret_hunk(map_tab == self.compare_left_tab);
            } else if multi_caret_ticks.len() >= 2 {
                self.state.status = format!(
                    "Document Map → caret line {} · {} carets",
                    line_idx + 1,
                    multi_caret_ticks.len()
                );
            } else {
                self.state.status = format!("Document Map → caret line {}", line_idx + 1);
            }
        } else if let Some(line_idx) = compare_click_line {
            if let Some(doc) = self.state.tabs.get_mut(map_tab) {
                let at = doc
                    .buffer
                    .line_to_char(line_idx.min(doc.buffer.line_count().saturating_sub(1)));
                doc.buffer.set_caret(at);
            }
            if secondary {
                self.follow_caret_other = true;
                if self.sync_scroll_v {
                    self.follow_caret = true;
                }
            } else {
                self.follow_caret = true;
                if self.sync_scroll_v {
                    self.follow_caret_other = true;
                }
            }
            // Parks partner + selects hunk (or Equal partner); sets Compare status.
            self.sync_compare_other_to_caret_hunk(map_tab == self.compare_left_tab);
        } else if let Some(line) = jump_line {
            if secondary {
                self.scroll_line_other = line;
                self.follow_caret_other = false;
                if self.dual_view && (self.sync_scroll_v || self.sync_scroll_h) {
                    self.scroll_line = line;
                    self.follow_caret = false;
                }
            } else {
                self.scroll_line = line;
                self.follow_caret = false;
                if self.dual_view && (self.sync_scroll_v || self.sync_scroll_h) {
                    self.scroll_line_other = line;
                    self.follow_caret_other = false;
                }
            }
            self.state.status = format!("Document Map → line {}", line as usize + 1);
        }
        if self.show_doc_map != open {
            self.state.settings.show_document_map = open;
            self.state.settings.save();
        }
        self.show_doc_map = open;
    }

    fn func_list_window(&mut self, ctx: &egui::Context) {
        if !self.show_func_list {
            return;
        }
        let entries = collect_func_like_lines(&self.state.tabs.active().buffer);
        let mut open = self.show_func_list;
        let mut jump: Option<usize> = None;
        egui::Window::new("Function List")
            .open(&mut open)
            .default_width(360.0)
            .default_height(320.0)
            .show(ctx, |ui| {
                if entries.is_empty() {
                    ui.label("No fn/class-like lines found.");
                } else {
                    egui::ScrollArea::vertical()
                        .max_height(280.0)
                        .show(ui, |ui| {
                            for (line_idx, preview) in &entries {
                                let label = format!("{}: {preview}", line_idx + 1);
                                if ui.selectable_label(false, label).clicked() {
                                    jump = Some(*line_idx);
                                }
                            }
                        });
                }
            });
        if let Some(line) = jump {
            let at = self.state.tabs.active().buffer.line_to_char(line);
            self.state.tabs.active_mut().buffer.set_caret(at);
            self.follow_caret = true;
            self.state.status = format!("Function List → line {}", line + 1);
        }
        self.show_func_list = open;
    }

    fn ollama_chat_window(&mut self, ctx: &egui::Context) {
        if !self.state.ollama_chat.open {
            return;
        }
        let mut open = self.state.ollama_chat.open;
        let mut send = false;
        let mut ask_editor = false;
        let mut clear = false;
        let mut open_tab = false;
        let busy = self.state.ollama_busy;
        let model = self.state.settings.ollama_model.trim().to_string();
        let host = self.state.settings.ollama_host.trim().to_string();
        let scope = self.state.ollama_chat.last_scope.clone();
        let thinking_secs = self.state.ollama_busy_since.map(|t| t.elapsed().as_secs());
        let entries = self.state.ollama_chat.entries.clone();

        egui::Window::new("Ollama Chat")
            .open(&mut open)
            .default_width(420.0)
            .default_height(480.0)
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    ui.label(RichText::new(format!("Model: {model}")).small().weak());
                    ui.label(RichText::new(format!("· {host}")).small().weak());
                    if !scope.is_empty() {
                        ui.label(RichText::new(format!("· {scope}")).small().weak());
                    }
                });
                ui.label(
                    RichText::new(
                        "You see the exact text sent below. Loopback only. Keep editing while it thinks.",
                    )
                    .small()
                    .weak(),
                );
                ui.separator();
                egui::ScrollArea::vertical()
                    .stick_to_bottom(true)
                    .max_height(280.0)
                    .show(ui, |ui| {
                        if entries.is_empty() && !busy {
                            ui.label(
                                RichText::new(
                                    "Ask Ollama sends the selection (or whole buffer). Or type a message below.",
                                )
                                .weak(),
                            );
                        }
                        for e in &entries {
                            match e.role {
                                crate::editor::OllamaChatRole::User => {
                                    ui.label(RichText::new("You").strong().color(MENU_READY));
                                    ui.label(&e.text);
                                    ui.add_space(8.0);
                                }
                                crate::editor::OllamaChatRole::Assistant => {
                                    ui.label(
                                        RichText::new("Ollama")
                                            .strong()
                                            .color(Color32::from_rgb(120, 160, 220)),
                                    );
                                    ui.label(&e.text);
                                    ui.add_space(8.0);
                                }
                                crate::editor::OllamaChatRole::Meta => {
                                    ui.label(RichText::new(&e.text).small().weak());
                                    ui.add_space(4.0);
                                }
                            }
                        }
                        if busy {
                            ui.horizontal(|ui| {
                                ui.spinner();
                                let secs = thinking_secs.unwrap_or(0);
                                ui.label(
                                    RichText::new(format!("Thinking… {secs}s"))
                                        .strong()
                                        .color(Color32::from_rgb(220, 180, 100)),
                                );
                            });
                        }
                    });
                ui.separator();
                ui.checkbox(
                    &mut self.state.ollama_chat.attach_editor,
                    "Attach selection / buffer with Send",
                );
                ui.add(
                    egui::TextEdit::multiline(&mut self.state.ollama_chat.input)
                        .desired_width(f32::INFINITY)
                        .desired_rows(3)
                        .hint_text("Ask a follow-up, or leave empty and use Ask editor…"),
                );
                ui.horizontal(|ui| {
                    if ui
                        .add_enabled(!busy, egui::Button::new("Send"))
                        .on_hover_text("Send the chat line (and optional editor attach)")
                        .clicked()
                    {
                        send = true;
                    }
                    if ui
                        .add_enabled(!busy, egui::Button::new("Ask editor…"))
                        .on_hover_text("Send selection or whole buffer (same as Ask Ollama)")
                        .clicked()
                    {
                        ask_editor = true;
                    }
                    if ui.button("Clear").clicked() {
                        clear = true;
                    }
                    if ui
                        .add_enabled(
                            self.state.ollama_chat.last_reply.is_some(),
                            egui::Button::new("Open reply in tab"),
                        )
                        .clicked()
                    {
                        open_tab = true;
                    }
                });
            });

        self.state.ollama_chat.open = open;
        if send {
            self.state.send_ollama_chat();
        }
        if ask_editor {
            self.state.ask_ollama();
        }
        if clear {
            self.state.clear_ollama_chat();
        }
        if open_tab {
            self.state.open_ollama_reply_tab();
        }
        if self.state.ollama_busy {
            ctx.request_repaint_after(std::time::Duration::from_millis(200));
        }
    }

    fn char_panel_window(&mut self, ctx: &egui::Context) {
        if !self.show_char_panel {
            return;
        }
        let mut open = self.show_char_panel;
        let mut insert: Option<char> = None;
        const CHARS: &[char] = &[
            '!', '@', '#', '$', '%', '^', '&', '*', '(', ')', '-', '_', '=', '+', '[', ']', '{',
            '}', '\\', '|', ';', ':', '\'', '"', ',', '.', '<', '>', '/', '?', '~', '`', '©', '®',
            '™', '€', '£', '¥', '§', '¶', '°', '±', '×', '÷', '½', '¼', '¾', '…', '–', '—', '‘',
            '’', '“', '”', '«', '»', '•', '†', '‡', 'α', 'β', 'γ', 'δ', 'π', 'μ', 'Ω', '←', '→',
            '↑', '↓', '✓', '✗', '★', '☆', '♠', '♣', '♥', '♦', '☺', '☻', '♪', '♫', '∞', '≈', '≠',
            '≤', '≥', '√', '∑', '∏', '∫', '∂', '∆', '∈', '∉', '∩', '∪', '⊂',
        ];
        egui::Window::new("Character Panel")
            .open(&mut open)
            .default_width(320.0)
            .show(ctx, |ui| {
                ui.label("Click a character to insert at the caret.");
                egui::ScrollArea::vertical()
                    .max_height(240.0)
                    .show(ui, |ui| {
                        ui.horizontal_wrapped(|ui| {
                            for &c in CHARS {
                                if ui
                                    .add_sized([28.0, 28.0], egui::Button::new(c.to_string()))
                                    .clicked()
                                {
                                    insert = Some(c);
                                }
                            }
                        });
                    });
            });
        if let Some(c) = insert {
            if self.state.tabs.active().read_only {
                self.state.status = "Document is read-only".into();
            } else {
                let s = c.to_string();
                self.state.prepare_edit();
                self.state.tabs.active_mut().buffer.insert(&s);
                self.state.mark_text_changed();
                self.follow_caret = true;
                self.state.status = format!("Inserted U+{:04X}", c as u32);
            }
        }
        self.show_char_panel = open;
    }

    fn tab_bar(&mut self, ctx: &egui::Context) {
        egui::TopBottomPanel::top("tabs").show(ctx, |ui| {
            ui.horizontal(|ui| {
                let count = self.state.tabs.len();
                let mut switch_to = None;
                let mut close_idx = None;
                let mut toggle_pin = None;
                let mut pending_move: Option<(usize, usize)> = None;
                let mut start_compare_now = false;
                for i in 0..count {
                    let Some(doc) = self.state.tabs.get(i) else {
                        continue;
                    };
                    let pinned = doc.pinned;
                    let mut label = String::new();
                    if pinned {
                        label.push_str("[P] ");
                    }
                    label.push_str(&doc.title);
                    if doc.dirty {
                        label.push('*');
                    }
                    if doc.tail_follow {
                        label.push_str(" [tail]");
                    }
                    if doc.loading {
                        label.push_str(" …");
                    }
                    let selected = i == self.state.tabs.active_index();
                    let is_partner = self.compare_partner_tab == Some(i) && !selected;
                    if is_partner {
                        label.push_str(" ⇄");
                    }
                    let colour = match doc.tab_colour {
                        Some(1) => Some(Color32::from_rgb(180, 70, 70)),
                        Some(2) => Some(Color32::from_rgb(70, 140, 80)),
                        Some(3) => Some(Color32::from_rgb(70, 110, 180)),
                        Some(4) => Some(Color32::from_rgb(160, 120, 40)),
                        Some(5) => Some(Color32::from_rgb(140, 70, 160)),
                        _ => None,
                    };
                    let text = if let Some(c) = colour {
                        RichText::new(&label).color(c)
                    } else if is_partner {
                        RichText::new(&label).color(Color32::from_rgb(40, 120, 140))
                    } else {
                        RichText::new(&label)
                    };
                    let resp = ui.add(
                        egui::Button::new(text)
                            .selected(selected)
                            .sense(Sense::click_and_drag()),
                    );
                    if resp.drag_started() {
                        self.tab_drag_from = Some(i);
                        switch_to = Some(i);
                    }
                    if resp.dragged() {
                        ctx.set_cursor_icon(egui::CursorIcon::Grabbing);
                    }
                    if self.tab_drag_from.is_some() && resp.hovered() {
                        if let Some(from) = self.tab_drag_from {
                            if from != i {
                                pending_move = Some((from, i));
                            }
                        }
                    }
                    if resp.clicked() {
                        let mod_pick = ui.input(|inp| inp.modifiers.command || inp.modifiers.ctrl);
                        if mod_pick && i != self.state.tabs.active_index() {
                            if self.compare_partner_tab == Some(i) {
                                self.compare_partner_tab = None;
                                self.state.status = "Compare partner cleared".into();
                            } else {
                                self.compare_partner_tab = Some(i);
                                self.state.status = format!(
                                    "Compare partner: “{}” — View → Compare with Other View",
                                    doc.title
                                );
                            }
                        } else {
                            switch_to = Some(i);
                        }
                    }
                    if resp.middle_clicked() {
                        close_idx = Some(i);
                    }
                    resp.context_menu(|ui| {
                        let pin_chord = crate::shortcut_chord::resolve_chord(
                            &self.state.settings.shortcut_pin_tab,
                            crate::shortcut_chord::DEFAULT_PIN_TAB,
                        )
                        .display();
                        let pin_label = if pinned {
                            format!("Unpin tab ({pin_chord})")
                        } else {
                            format!("Pin tab ({pin_chord})")
                        };
                        if ui.button(pin_label).clicked() {
                            toggle_pin = Some(i);
                            ui.close_menu();
                        }
                        if i != self.state.tabs.active_index() {
                            let mark_label = if self.compare_partner_tab == Some(i) {
                                "Clear compare partner"
                            } else {
                                "Mark for compare"
                            };
                            if ui.button(mark_label).clicked() {
                                if self.compare_partner_tab == Some(i) {
                                    self.compare_partner_tab = None;
                                    self.state.status = "Compare partner cleared".into();
                                } else {
                                    self.compare_partner_tab = Some(i);
                                    self.state.status = format!(
                                        "Compare partner: “{}” — View → Compare with Other View",
                                        doc.title
                                    );
                                }
                                ui.close_menu();
                            }
                            if ui.button("Compare with this tab").clicked() {
                                self.compare_partner_tab = Some(i);
                                start_compare_now = true;
                                ui.close_menu();
                            }
                        }
                    });
                    ui.push_id(("pin_tab", i), |ui| {
                        let pin_btn = if pinned { "P" } else { "·" };
                        let pin_chord = crate::shortcut_chord::resolve_chord(
                            &self.state.settings.shortcut_pin_tab,
                            crate::shortcut_chord::DEFAULT_PIN_TAB,
                        )
                        .display();
                        let pin_tip = if pinned {
                            format!("Unpin tab ({pin_chord}; Preferences remappable)")
                        } else {
                            format!("Pin tab ({pin_chord}; Preferences remappable)")
                        };
                        if ui.small_button(pin_btn).on_hover_text(pin_tip).clicked() {
                            toggle_pin = Some(i);
                        }
                    });
                    ui.push_id(("close_tab", i), |ui| {
                        if ui.small_button("×").on_hover_text("Close tab").clicked() {
                            close_idx = Some(i);
                        }
                    });
                }
                if let Some((from, to)) = pending_move {
                    if self.state.tabs.move_tab(from, to) {
                        self.remap_tab_indices(from, to);
                        self.tab_drag_from = Some(to);
                        self.state.status = "Tab moved".into();
                    }
                }
                if !ui.input(|i| i.pointer.any_down()) {
                    self.tab_drag_from = None;
                }
                if ui.button("+").clicked() {
                    self.state.new_file();
                }
                if self.dual_view {
                    ui.separator();
                    let other_title = self
                        .state
                        .tabs
                        .get(self.other_view_tab)
                        .map(|d| d.title.clone())
                        .unwrap_or_else(|| "?".into());
                    ui.label(
                        RichText::new(format!("| other: {other_title}"))
                            .small()
                            .weak(),
                    );
                    if ui
                        .small_button("×dual")
                        .on_hover_text("Close dual view")
                        .clicked()
                    {
                        self.dual_view = false;
                        self.focused_pane = EditorPane::Primary;
                        self.state.status = "Dual view closed".into();
                    }
                }
                if let Some(i) = toggle_pin {
                    if let Some(doc) = self.state.tabs.get_mut(i) {
                        doc.pinned = !doc.pinned;
                        let name = doc.title.clone();
                        let on = doc.pinned;
                        self.state.status = if on {
                            format!("Pinned “{name}”")
                        } else {
                            format!("Unpinned “{name}”")
                        };
                    }
                }
                if let Some(i) = switch_to {
                    self.persist_primary_tab_scroll();
                    self.state.tabs.set_active(i);
                    self.state.highlight_dirty = true;
                }
                if let Some(i) = close_idx {
                    self.persist_primary_tab_scroll();
                    self.state.request_close_tab(i);
                    self.apply_closed_tab_indices();
                }
                if start_compare_now {
                    self.start_compare();
                }
            });
        });
    }

    fn remap_tab_indices(&mut self, from: usize, to: usize) {
        use doc::TabSet;
        self.other_view_tab = TabSet::remap_index(self.other_view_tab, from, to);
        self.compare_left_tab = TabSet::remap_index(self.compare_left_tab, from, to);
        self.compare_right_tab = TabSet::remap_index(self.compare_right_tab, from, to);
        if let Some(p) = self.compare_partner_tab {
            self.compare_partner_tab = Some(TabSet::remap_index(p, from, to));
        }
        self.state.remap_highlight_tab_other(from, to);
    }

    fn seed_find_from_selection(&mut self) {
        if let Some((s, e)) = self.state.tabs.active().buffer.selection() {
            let sel = self.state.tabs.active().buffer.slice(s, e);
            if !sel.is_empty() && !sel.contains('\n') && sel.chars().count() <= 200 {
                self.state.find_query = sel;
            }
        }
    }

    fn find_replace_bar(&mut self, ctx: &egui::Context) {
        egui::TopBottomPanel::top("find").show(ctx, |ui| {
            let mut persist = false;
            let mut run_find_files = false;
            let mut run_find_all = false;
            let mut run_find_all_opened = false;
            ui.horizontal(|ui| {
                ui.label("Find:");
                let resp = ui
                    .add(
                        egui::TextEdit::singleline(&mut self.state.find_query)
                            .desired_width(180.0)
                            .hint_text("search text"),
                    )
                    .on_hover_text(
                        "Enter: Find Next. Shift+Enter: Find Previous (same as Prev button)",
                    );
                // Selection drag → drop into Find field (fills query; does not move text).
                if self.sel_text_drag.is_some() {
                    let over_find = ui
                        .input(|i| i.pointer.latest_pos())
                        .is_some_and(|p| resp.rect.contains(p));
                    if let Some(drag) = self.sel_text_drag.as_mut() {
                        if over_find {
                            drag.drop_bar = SelDropBar::Find;
                        } else if drag.drop_bar == SelDropBar::Find {
                            drag.drop_bar = SelDropBar::None;
                        }
                    }
                    if over_find {
                        ui.ctx().set_cursor_icon(CursorIcon::Copy);
                        let stroke = egui::Stroke::new(2.0_f32, Color32::from_rgb(220, 140, 40));
                        ui.painter().rect_stroke(
                            resp.rect.expand(2.0),
                            2.0,
                            stroke,
                            egui::StrokeKind::Outside,
                        );
                        if self.state.status != "Drop selection into Find" {
                            self.state.status = "Drop selection into Find".into();
                        }
                    }
                }
                if resp.changed() {
                    persist = true;
                    if self.state.find_incremental {
                        self.state.find_incremental_update();
                        self.follow_caret = true;
                    }
                }
                let (enter, shift_enter) =
                    ui.input(|i| (i.key_pressed(Key::Enter), i.modifiers.shift));
                if resp.has_focus() && enter {
                    if shift_enter {
                        self.state.find_prev();
                    } else {
                        self.state.find_next();
                    }
                    self.follow_caret = true;
                }
                if ui
                    .button("Next")
                    .on_hover_text("Find Next (Enter in the Find field)")
                    .clicked()
                {
                    self.state.find_next();
                    self.follow_caret = true;
                }
                if ui
                    .button("Prev")
                    .on_hover_text("Find Previous (Shift+Enter in the Find field)")
                    .clicked()
                {
                    self.state.find_prev();
                    self.follow_caret = true;
                }
                let mut find_opts_changed = false;
                if ui
                    .checkbox(&mut self.state.settings.find_match_case, "Case")
                    .changed()
                {
                    persist = true;
                    find_opts_changed = true;
                }
                if ui
                    .checkbox(&mut self.state.settings.find_whole_word, "Word")
                    .changed()
                {
                    persist = true;
                    find_opts_changed = true;
                }
                if ui
                    .checkbox(&mut self.state.settings.find_in_selection, "Sel")
                    .on_hover_text(
                        "Find and replace only in a captured range (auto on for multi-line selection)",
                    )
                    .changed()
                {
                    persist = true;
                    find_opts_changed = true;
                    if self.state.settings.find_in_selection {
                        self.state.capture_find_scope();
                    } else {
                        self.state.find_scope = None;
                    }
                }
                if ui
                    .checkbox(&mut self.state.settings.find_wrap, "Wrap")
                    .on_hover_text("After the last match, Next starts again at the first")
                    .changed()
                {
                    persist = true;
                    find_opts_changed = true;
                }
                if ui
                    .checkbox(&mut self.state.settings.find_regex, "Re")
                    .on_hover_text(
                        "Treat the query as a regular expression (linear-time). Replace: $n or \\n for groups",
                    )
                    .changed()
                {
                    persist = true;
                    find_opts_changed = true;
                }
                if ui
                    .checkbox(&mut self.state.find_incremental, "Inc")
                    .on_hover_text({
                        let chord = crate::shortcut_chord::resolve_chord(
                            &self.state.settings.shortcut_find_incremental,
                            crate::shortcut_chord::DEFAULT_FIND_INCREMENTAL,
                        );
                        format!(
                            "Incremental Search: typing in Find jumps to the match (Search → Incremental Search; {})",
                            chord.display()
                        )
                    })
                    .changed()
                    && self.state.find_incremental
                    && !self.state.find_query.is_empty()
                {
                    find_opts_changed = true;
                }
                if find_opts_changed && self.state.find_incremental && !self.state.find_query.is_empty()
                {
                    self.state.find_incremental_update();
                    self.follow_caret = true;
                }
                let n = self.state.find_match_count();
                if self.state.find_query.is_empty() {
                    ui.label(RichText::new("0 matches").weak());
                } else {
                    ui.label(format!("{n} match{}", if n == 1 { "" } else { "es" }));
                }
                if ui
                    .button("Mark")
                    .on_hover_text({
                        let chord = crate::shortcut_chord::resolve_chord(
                            &self.state.settings.shortcut_find_mark,
                            crate::shortcut_chord::DEFAULT_FIND_MARK,
                        );
                        format!(
                            "Style all matching lines with Style 1 (Case / Word / Re / Sel; Search → Mark; {})",
                            chord.display()
                        )
                    })
                    .clicked()
                {
                    self.state.mark_all_style(1, true);
                }
                if ui
                    .button("Bookmark")
                    .on_hover_text({
                        let chord = crate::shortcut_chord::resolve_chord(
                            &self.state.settings.shortcut_find_bookmark,
                            crate::shortcut_chord::DEFAULT_FIND_BOOKMARK,
                        );
                        format!(
                            "Bookmark all matching lines (Case / Word / Re / Sel; keeps existing; {})",
                            chord.display()
                        )
                    })
                    .clicked()
                {
                    let _ = self.state.bookmark_find_matches();
                }
                if ui
                    .button("Copy")
                    .on_hover_text({
                        let chord = crate::shortcut_chord::resolve_chord(
                            &self.state.settings.shortcut_find_copy,
                            crate::shortcut_chord::DEFAULT_FIND_COPY,
                        );
                        format!(
                            "Copy matching text to clipboard (Case / Word / Re / Sel; one match per line; {})",
                            chord.display()
                        )
                    })
                    .clicked()
                {
                    if let Some(text) = self.state.copy_find_matches() {
                        if !text.is_empty() {
                            self.remember_clipboard(&text);
                            ctx.copy_text(text);
                        }
                    }
                }
                if ui
                    .button("Lines")
                    .on_hover_text({
                        let chord = crate::shortcut_chord::resolve_chord(
                            &self.state.settings.shortcut_find_copy,
                            crate::shortcut_chord::DEFAULT_FIND_COPY,
                        );
                        format!(
                            "Copy matching lines to clipboard (Case / Word / Re / Sel; whole lines, deduped; {})",
                            chord.flipped_shift().display()
                        )
                    })
                    .clicked()
                {
                    if let Some(text) = self.state.copy_find_match_lines() {
                        if !text.is_empty() {
                            self.remember_clipboard(&text);
                            ctx.copy_text(text);
                        }
                    }
                }
                let cut_lines = ui.input(|i| i.modifiers.shift);
                if ui
                    .button("Cut")
                    .on_hover_text({
                        let chord = crate::shortcut_chord::resolve_chord(
                            &self.state.settings.shortcut_find_cut,
                            crate::shortcut_chord::DEFAULT_FIND_CUT,
                        );
                        format!(
                            "Cut matching text to clipboard and delete matches (Case / Word / Re / Sel; one match per line; {}). Shift ({}): cut matching lines (whole lines, deduped)",
                            chord.display(),
                            chord.flipped_shift().display()
                        )
                    })
                    .clicked()
                {
                    if cut_lines {
                        if let Some(text) = self.state.cut_find_match_lines() {
                            if !text.is_empty() {
                                self.remember_clipboard(&text);
                                ctx.copy_text(text);
                            }
                        }
                    } else if let Some(text) = self.state.cut_find_matches() {
                        if !text.is_empty() {
                            self.remember_clipboard(&text);
                            ctx.copy_text(text);
                        }
                    }
                }
                let purge_matches = ui.input(|i| i.modifiers.shift);
                if ui
                    .button("Purge")
                    .on_hover_text({
                        let chord = crate::shortcut_chord::resolve_chord(
                            &self.state.settings.shortcut_find_purge,
                            crate::shortcut_chord::DEFAULT_FIND_PURGE,
                        );
                        format!(
                            "Delete every line that contains a match (Case / Word / Re / Sel; whole lines; {}). Shift ({}): delete matching substrings only (no clipboard)",
                            chord.display(),
                            chord.flipped_shift().display()
                        )
                    })
                    .clicked()
                {
                    if purge_matches {
                        let _ = self.state.delete_find_matches();
                    } else {
                        let _ = self.state.delete_find_match_lines();
                    }
                }
                let find_all_opened = ui.input(|i| i.modifiers.shift);
                if ui
                    .button("All")
                    .on_hover_text({
                        let chord = crate::shortcut_chord::resolve_chord(
                            &self.state.settings.shortcut_find_all,
                            crate::shortcut_chord::DEFAULT_FIND_ALL,
                        );
                        format!(
                            "Find All in current document: open Find Results tab (Case / Word / Re / Sel; line:col:match). Same as Search → Search Results Window ({}). Shift ({}): all opened editor tabs (Case / Word / Re; Sel ignored)",
                            chord.display(),
                            chord.flipped_shift().display()
                        )
                    })
                    .clicked()
                {
                    if find_all_opened {
                        run_find_all_opened = true;
                    } else {
                        run_find_all = true;
                    }
                }
                if self.show_replace {
                    ui.separator();
                    ui.label("Replace:");
                    let rresp = ui
                        .add(egui::TextEdit::singleline(&mut self.replace_with).desired_width(120.0))
                        .on_hover_text(
                            "Enter: Replace once (same as Replace). Shift+Enter: Replace All. With Re: $1 / \\1 insert a capture, $0 / $& the match, $$ a dollar",
                        );
                    // Selection drag → drop into Replace field (fills replace text; does not move).
                    if self.sel_text_drag.is_some() {
                        let over_replace = ui
                            .input(|i| i.pointer.latest_pos())
                            .is_some_and(|p| rresp.rect.contains(p));
                        if let Some(drag) = self.sel_text_drag.as_mut() {
                            if over_replace {
                                drag.drop_bar = SelDropBar::Replace;
                            } else if drag.drop_bar == SelDropBar::Replace {
                                drag.drop_bar = SelDropBar::None;
                            }
                        }
                        if over_replace {
                            ui.ctx().set_cursor_icon(CursorIcon::Copy);
                            let stroke =
                                egui::Stroke::new(2.0_f32, Color32::from_rgb(220, 140, 40));
                            ui.painter().rect_stroke(
                                rresp.rect.expand(2.0),
                                2.0,
                                stroke,
                                egui::StrokeKind::Outside,
                            );
                            if self.state.status != "Drop selection into Replace" {
                                self.state.status = "Drop selection into Replace".into();
                            }
                        }
                    }
                    if rresp.changed() {
                        persist = true;
                    }
                    // Enter / Shift+Enter while Replace field focused (mirrors Find Next/Prev chords).
                    let (replace_enter, replace_shift) =
                        ui.input(|i| (i.key_pressed(Key::Enter), i.modifiers.shift));
                    if rresp.has_focus() && replace_enter {
                        let r = self.replace_with.clone();
                        if replace_shift {
                            self.state.replace_all(&r);
                        } else {
                            self.state.replace_next(&r);
                            self.follow_caret = true;
                        }
                    }
                    if ui
                        .button("Replace")
                        .on_hover_text("Replace once (Enter in the Replace field)")
                        .clicked()
                    {
                        let r = self.replace_with.clone();
                        self.state.replace_next(&r);
                        self.follow_caret = true;
                    }
                    if ui
                        .button("Replace All")
                        .on_hover_text("Replace all matches (Shift+Enter in the Replace field)")
                        .clicked()
                    {
                        let r = self.replace_with.clone();
                        self.state.replace_all(&r);
                    }
                } else if ui.button("Replace…").clicked() {
                    self.show_replace = true;
                }
                if ui.button("Close").clicked() {
                    persist = true;
                    self.state.find_open = false;
                    self.show_replace = false;
                    self.state.find_incremental = false;
                }
                if self.find_focus_once {
                    resp.request_focus();
                    self.find_focus_once = false;
                }
            });
            ui.horizontal(|ui| {
                ui.label("In files:");
                let inc = ui.add(
                    egui::TextEdit::singleline(&mut self.state.settings.find_files_include)
                        .desired_width(140.0)
                        .hint_text("*.rs,*.md (empty=all)"),
                );
                if inc.changed() {
                    persist = true;
                }
                ui.label("Exclude:");
                let exc = ui.add(
                    egui::TextEdit::singleline(&mut self.state.settings.find_files_exclude)
                        .desired_width(160.0)
                        .hint_text("target,node_modules"),
                );
                if exc.changed() {
                    persist = true;
                }
                if ui
                    .button("Find in Files")
                    .on_hover_text({
                        let chord = crate::shortcut_chord::resolve_chord(
                            &self.state.settings.shortcut_find_in_files,
                            crate::shortcut_chord::DEFAULT_FIND_IN_FILES,
                        )
                        .display();
                        format!("Search workspace root recursively ({chord})")
                    })
                    .clicked()
                {
                    persist = true;
                    run_find_files = true;
                }
            });
            if persist {
                self.state.settings.find_query = self.state.find_query.clone();
                self.state.settings.replace_with = self.replace_with.clone();
                self.state.settings.save();
            }
            if run_find_all || run_find_all_opened {
                let mut flags = crate::commands::UiFlags {
                    find_open: self.state.find_open,
                    show_replace: self.show_replace,
                    find_focus_once: self.find_focus_once,
                    follow_caret: self.follow_caret,
                    ..Default::default()
                };
                let cmd = if run_find_all_opened {
                    "IDM_SEARCH_FINDALLINOPENEDDOCS"
                } else {
                    "IDM_FOCUS_ON_FOUND_RESULTS"
                };
                let _ = self.dispatch_menu_cmd(cmd, &mut flags);
                self.state.find_open = flags.find_open;
                self.show_replace = flags.show_replace;
                self.find_focus_once = flags.find_focus_once;
                if flags.follow_caret {
                    self.follow_focused_caret();
                }
            }
            if run_find_files {
                let mut flags = crate::commands::UiFlags {
                    find_open: self.state.find_open,
                    show_replace: self.show_replace,
                    find_focus_once: self.find_focus_once,
                    follow_caret: self.follow_caret,
                    ..Default::default()
                };
                let _ = self.dispatch_menu_cmd("IDM_SEARCH_FINDINFILES", &mut flags);
                self.state.find_open = flags.find_open;
                self.show_replace = flags.show_replace;
                self.find_focus_once = flags.find_focus_once;
                if flags.follow_caret {
                    self.follow_focused_caret();
                }
            }
        });
    }

    fn status_bar(&mut self, ctx: &egui::Context) {
        egui::TopBottomPanel::bottom("status").show(ctx, |ui| {
            let (lang, line, col, chars, on, status, chg_u, chg_s) = {
                let doc = self.state.tabs.active();
                let caret = doc.buffer.caret();
                let line = doc.buffer.char_to_line(caret);
                let col = caret - doc.buffer.line_to_char(line) + 1;
                let (chg_u, chg_s) = doc.change_history_counts();
                (
                    doc.language.clone(),
                    line + 1,
                    col,
                    doc.buffer.len_chars(),
                    doc.tail_follow,
                    self.state.status.clone(),
                    chg_u,
                    chg_s,
                )
            };
            ui.horizontal(|ui| {
                ui.label(&status);
                if crate::commands::edit::text_is_rtl() {
                    ui.separator();
                    ui.label(
                        RichText::new("RTL")
                            .strong()
                            .color(Color32::from_rgb(42, 148, 118)),
                    );
                }

                ui.separator();
                // Clickable tail toggle (same as View → Monitoring).
                let tail_text = if on {
                    RichText::new("TAIL").strong().color(MENU_READY)
                } else {
                    RichText::new("tail").weak()
                };
                if ui
                    .add(egui::Button::new(tail_text).frame(false))
                    .on_hover_text(if on {
                        "Tail ON — click to stop following the file"
                    } else {
                        "Click to tail this file (Monitoring / ⌘⇧T)"
                    })
                    .clicked()
                    && self.state.toggle_tail_follow()
                {
                    self.follow_caret = true;
                }
                if chg_u + chg_s > 0 {
                    ui.separator();
                    let label = format!("CHG {chg_u}/{chg_s}");
                    let color = if chg_u > 0 {
                        Color32::from_rgb(210, 140, 40)
                    } else {
                        Color32::from_rgb(70, 160, 90)
                    };
                    ui.label(RichText::new(label).color(color)).on_hover_text(
                        "Change history: unsaved (amber) / saved (green) line marks",
                    );
                }
                if self.state.settings.status_show_lang {
                    ui.separator();
                    ui.label(format!("Lang: {lang}"));
                }
                ui.separator();
                ui.label(format!("Ln {line}, Col {col}"));
                if self.state.settings.status_show_chars {
                    ui.separator();
                    ui.label(format!("{chars} chars"));
                }

                // Bottom-right: package version + git commit → GitHub.
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    let short = env!("NPP_GIT_HASH");
                    let full = env!("NPP_GIT_HASH_FULL");
                    let ver = env!("CARGO_PKG_VERSION");
                    let label = format!("v{ver} · {short}");
                    let url = format!("https://github.com/raro42/npp-rust/commit/{full}");
                    ui.hyperlink_to(RichText::new(label).small().weak(), url)
                        .on_hover_text("Open this build’s commit on GitHub (raro42/npp-rust)");
                });
            });
        });
    }

    fn editor_pane(&mut self, ctx: &egui::Context) {
        self.state
            .refresh_highlight_if_needed(self.scroll_line.floor() as usize);
        self.apply_closed_tab_indices();
        self.clamp_other_view_tab();
        self.sync_compare_panes();
        if self.dual_view {
            let other_scroll = if self.sync_scroll_v || self.sync_scroll_h {
                self.scroll_line
            } else {
                self.scroll_line_other
            };
            self.state.refresh_highlight_other_if_needed(
                self.other_view_tab,
                other_scroll.floor() as usize,
            );
        }

        if self.dual_view {
            let title = self
                .state
                .tabs
                .get(self.other_view_tab)
                .map(|d| d.title.clone())
                .unwrap_or_else(|| "Other view".into());
            egui::SidePanel::right("dual_other_view")
                .resizable(true)
                .default_width(420.0)
                .min_width(180.0)
                .show(ctx, |ui| {
                    ui.horizontal(|ui| {
                        let focus_bit = if self.focused_pane == EditorPane::Secondary {
                            " · focused"
                        } else {
                            ""
                        };
                        ui.label(RichText::new(format!("Other view: {title}{focus_bit}")).strong());
                        let focus_chord = crate::shortcut_chord::resolve_chord(
                            &self.state.settings.shortcut_focus_other_view,
                            crate::shortcut_chord::DEFAULT_FOCUS_OTHER_VIEW,
                        );
                        if ui
                            .small_button("Focus")
                            .on_hover_text(format!(
                                "Toggle keyboard focus ({}; Preferences remappable)",
                                focus_chord.display()
                            ))
                            .clicked()
                        {
                            self.focus_other_view_now();
                        }
                        if ui
                            .small_button("Switch")
                            .on_hover_text(format!(
                                "Swap with active tab ({})",
                                focus_chord.flipped_shift().display()
                            ))
                            .clicked()
                        {
                            self.switch_other_view_now();
                        }
                    });
                    ui.separator();
                    self.paint_secondary_pane(ui);
                });
        }

        egui::CentralPanel::default().show(ctx, |ui| {
            if self.state.tabs.active().loading {
                ui.centered_and_justified(|ui| {
                    ui.label(RichText::new("Loading file…").size(18.0));
                });
                return;
            }

            let font_id = FontId::monospace(self.font_size);
            let row_height = ui.fonts(|f| f.row_height(&font_id)) + 2.0;
            let buf_line_count = self.state.tabs.active().buffer.line_count().max(1);
            let fold_hidden = self.state.tabs.active().hidden_lines.clone();
            let visible_lines = visible_lines_with_compare_hide(
                buf_line_count,
                &fold_hidden,
                self.compare_on,
                self.state.settings.compare_hide_equal,
                &self.compare_left_tags,
                &self.compare_hide_revealed_left,
                self.state.settings.compare_hide_equal_context_lines(),
            );
            let display_count = visible_lines.len().max(1);
            let avail = ui.available_size();
            let (rect, response) = ui.allocate_exact_size(avail, Sense::click_and_drag());
            let mut ctx_ask_ollama = false;
            response.context_menu(|ui| {
                if ui
                    .button("Ask Ollama")
                    .on_hover_text(
                        "Send selection (or whole buffer) to local Ollama; chat shows the prompt and Thinking…",
                    )
                    .clicked()
                {
                    ctx_ask_ollama = true;
                    ui.close_menu();
                }
            });
            if ctx_ask_ollama {
                self.state.ask_ollama();
            }
            // Do not steal focus every frame — that breaks Find (Ctrl/Cmd+F).
            if !self.state.find_open && !self.show_replace {
                if response.clicked() || response.drag_started() {
                    response.request_focus();
                    self.focused_pane = EditorPane::Primary;
                }
            } else if response.clicked() {
                // Clicking the editor closes find focus but keeps the bar open.
                response.request_focus();
                self.focused_pane = EditorPane::Primary;
            }

            if self.state.reset_view {
                self.scroll_line = 0.0;
                self.follow_caret = false;
                self.state.reset_view = false;
                let tab = self.state.tabs.active_index();
                if let Some(doc) = self.state.tabs.get_mut(tab) {
                    doc.view_scroll_line = 0;
                }
                self.last_primary_tab = Some(tab);
            }
            let visible_rows = {
                // One extra row of air above the status bar — last line must stay fully visible.
                let usable = (rect.height() - row_height).max(row_height);
                ((usable / row_height).floor() as usize).max(1)
            };
            self.doc_map_page_rows = visible_rows;
            let max_scroll = (display_count.saturating_sub(visible_rows) as f32).max(0.0);

            // Mouse-wheel scroll must not be overridden by caret-follow.
            // In dual view, only scroll this pane when the pointer is over it.
            // Cmd/Ctrl+wheel zooms (handled in handle_shortcuts); skip scroll then.
            let scroll = if !self.dual_view || response.hovered() {
                ui.input(|i| {
                    if i.modifiers.command || i.modifiers.ctrl {
                        0.0
                    } else {
                        i.raw_scroll_delta.y
                    }
                })
            } else {
                0.0
            };
            if scroll != 0.0 {
                self.follow_caret = false;
                self.scroll_line = (self.scroll_line - scroll / row_height).clamp(0.0, max_scroll);
                if self.dual_view && (self.sync_scroll_v || self.sync_scroll_h) {
                    self.scroll_line_other = self.scroll_line;
                }
            }

            let sync_scroll = self.dual_view && (self.sync_scroll_v || self.sync_scroll_h);
            let sb_layout = editor_scrollbar_layout(
                rect,
                self.scroll_line,
                max_scroll,
                visible_rows,
                display_count,
            );
            let mut scrollbar_consumed = false;
            if let Some(ScrollbarDrag {
                pane: EditorPane::Primary,
                grab_offset_y,
            }) = self.scrollbar_drag
            {
                if ui.input(|i| i.pointer.primary_down()) {
                    if let (Some(pos), Some(layout)) =
                        (ui.input(|i| i.pointer.interact_pos()), sb_layout.as_ref())
                    {
                        self.scroll_line = scroll_line_from_scrollbar_pointer(
                            pos.y,
                            grab_offset_y,
                            layout,
                            max_scroll,
                        );
                        self.follow_caret = false;
                        if sync_scroll {
                            self.scroll_line_other = self.scroll_line;
                        }
                        scrollbar_consumed = true;
                        ui.ctx().set_cursor_icon(CursorIcon::ResizeVertical);
                    }
                } else {
                    self.scrollbar_drag = None;
                }
            }
            if !scrollbar_consumed && (response.clicked() || response.drag_started()) {
                if let (Some(pos), Some(layout)) =
                    (response.interact_pointer_pos(), sb_layout.as_ref())
                {
                    if layout.hit_track.contains(pos) {
                        let grab = if layout.thumb.contains(pos) {
                            (pos.y - layout.thumb.top()).clamp(0.0, layout.thumb.height())
                        } else {
                            layout.thumb.height() * 0.5
                        };
                        self.scroll_line =
                            scroll_line_from_scrollbar_pointer(pos.y, grab, layout, max_scroll);
                        self.follow_caret = false;
                        self.drag_anchor = None;
                        self.rect_drag = false;
                        self.rect_drag_anchor = None;
                        self.sel_text_drag = None;
                        self.scrollbar_drag = Some(ScrollbarDrag {
                            pane: EditorPane::Primary,
                            grab_offset_y: grab,
                        });
                        if sync_scroll {
                            self.scroll_line_other = self.scroll_line;
                        }
                        scrollbar_consumed = true;
                        ui.ctx().set_cursor_icon(CursorIcon::ResizeVertical);
                    }
                }
            }

            let show_ln = self.state.settings.show_line_numbers;
            let show_fold = self.state.settings.show_fold_margin;
            let fold_w = if show_fold { FOLD_MARGIN_W } else { 0.0 };
            let gutter_w = if show_ln { 56.0 } else { 16.0 }
                + fold_w
                + f32::from(self.state.settings.gutter_extra);
            // Gap between line numbers and text (was flush before).
            let gutter_gap = 12.0;
            let text_left = rect.left() + gutter_w + gutter_gap;
            let gutter_right = rect.left() + gutter_w;
            let fold_left = gutter_right - fold_w;

            let hit_index = |ui: &egui::Ui,
                             pos: Pos2,
                             buf: &buffer::TextBuffer,
                             scroll: f32,
                             visible: &[usize]|
             -> usize {
                let first = scroll.floor() as usize;
                let row = first + ((pos.y - rect.top()) / row_height).floor().max(0.0) as usize;
                let row = row.min(visible.len().saturating_sub(1));
                let line = visible.get(row).copied().unwrap_or(0);
                let line_start = buf.line_to_char(line);
                let line_text = buf.line(line);
                let line_body = line_text.trim_end_matches(['\n', '\r']);
                let col = col_from_x(ui, &font_id, line_body, pos.x - text_left);
                line_start + col
            };

            let hit_line_col_virtual = |ui: &egui::Ui,
                                        pos: Pos2,
                                        buf: &buffer::TextBuffer,
                                        scroll: f32,
                                        visible: &[usize]|
             -> (usize, usize) {
                let first = scroll.floor() as usize;
                let row = first + ((pos.y - rect.top()) / row_height).floor().max(0.0) as usize;
                let row = row.min(visible.len().saturating_sub(1));
                let line = visible.get(row).copied().unwrap_or(0);
                let line_text = buf.line(line);
                let line_body = line_text.trim_end_matches(['\n', '\r']);
                let col = col_from_x_virtual(ui, &font_id, line_body, pos.x - text_left);
                (line, col)
            };

            let scroll_for_hit = self.scroll_line;
            let fold_line_at = |pos: Pos2| -> Option<usize> {
                if !show_fold || fold_w <= 0.0 || pos.x < fold_left || pos.x >= gutter_right {
                    return None;
                }
                let first = scroll_for_hit.floor() as usize;
                let row = first + ((pos.y - rect.top()) / row_height).floor().max(0.0) as usize;
                let row = row.min(visible_lines.len().saturating_sub(1));
                visible_lines.get(row).copied()
            };

            let mut fold_click = false;
            let mut hide_gap_click = false;
            if !scrollbar_consumed && (response.clicked() || response.drag_started()) {
                if let Some(pos) = response.interact_pointer_pos() {
                    if self.try_expand_compare_hide_gap_at(
                        pos,
                        rect,
                        scroll_for_hit,
                        row_height,
                        &visible_lines,
                        true,
                    ) {
                        hide_gap_click = true;
                        self.drag_anchor = None;
                        self.rect_drag = false;
                        self.rect_drag_anchor = None;
                        self.sel_text_drag = None;
                    } else if let Some(line) = fold_line_at(pos) {
                        let lang = self.state.tabs.active().language.clone();
                        let regions = crate::fold::compute_fold_regions(
                            lang.as_str(),
                            &self.state.tabs.active().buffer,
                        );
                        if let Some(region) = crate::fold::region_for_fold_action(&regions, line) {
                            let hidden = &mut self.state.tabs.active_mut().hidden_lines;
                            let was = crate::fold::is_folded(hidden, &region);
                            crate::fold::toggle_region(hidden, &region);
                            self.state.status = if was {
                                format!("Unfolded {} line(s)", region.end - region.header)
                            } else {
                                format!("Folded {} line(s)", region.end - region.header)
                            };
                            fold_click = true;
                            self.drag_anchor = None;
                            self.rect_drag = false;
                            self.rect_drag_anchor = None;
                            self.sel_text_drag = None;
                        }
                    }
                }
            }

            // Double-click → word; triple-click → line; click → caret;
            // Alt+drag → rect/column multi-carets; drag inside selection → move/copy;
            // else drag → select.
            if scrollbar_consumed || fold_click || hide_gap_click {
                // Scrollbar, fold margin, or hide-equal ···N cue consumed the pointer.
            } else if response.triple_clicked() {
                if let Some(pos) = response.interact_pointer_pos() {
                    let idx = hit_index(
                        ui,
                        pos,
                        &self.state.tabs.active().buffer,
                        self.scroll_line,
                        &visible_lines,
                    );
                    self.state.tabs.active_mut().clear_multi_sels();
                    self.state.tabs.active_mut().clear_virtual_caret();
                    self.state.tabs.active_mut().buffer.select_line_at(idx);
                    self.drag_anchor = None;
                    self.rect_drag = false;
                    self.rect_drag_anchor = None;
                    self.sel_text_drag = None;
                    self.follow_caret = false;
                }
            } else if response.double_clicked() {
                if let Some(pos) = response.interact_pointer_pos() {
                    let (line, _col) = hit_line_col_virtual(
                        ui,
                        pos,
                        &self.state.tabs.active().buffer,
                        self.scroll_line,
                        &visible_lines,
                    );
                    // Find Results / Find in Files: double-click a hit row → open + park match.
                    let results_tab = self.state.tabs.active_index();
                    let mut jump_flags = crate::commands::UiFlags::default();
                    if crate::commands::search::goto_search_result_at_line(
                        &mut self.state,
                        &mut jump_flags,
                        results_tab,
                        line,
                    ) {
                        self.drag_anchor = None;
                        self.rect_drag = false;
                        self.rect_drag_anchor = None;
                        self.sel_text_drag = None;
                        if jump_flags.follow_caret {
                            self.follow_caret = true;
                        }
                    } else {
                        let idx = hit_index(
                            ui,
                            pos,
                            &self.state.tabs.active().buffer,
                            self.scroll_line,
                            &visible_lines,
                        );
                        self.state.tabs.active_mut().clear_multi_sels();
                        self.state.tabs.active_mut().clear_virtual_caret();
                        self.state.tabs.active_mut().buffer.select_word_at(idx);
                        self.drag_anchor = None;
                        self.rect_drag = false;
                        self.rect_drag_anchor = None;
                        self.sel_text_drag = None;
                        self.follow_caret = false;
                    }
                }
            } else if response.drag_started() {
                if let Some(pos) = response.interact_pointer_pos() {
                    let idx = hit_index(
                        ui,
                        pos,
                        &self.state.tabs.active().buffer,
                        self.scroll_line,
                        &visible_lines,
                    );
                    let (shift, alt, ctrl_cmd) = ui.input(|i| {
                        (
                            i.modifiers.shift,
                            i.modifiers.alt,
                            i.modifiers.ctrl || i.modifiers.command,
                        )
                    });
                    let tab = self.state.tabs.active_index();
                    let doc = self.state.tabs.active();
                    let inside_sel = doc
                        .buffer
                        .selection()
                        .is_some_and(|(s, e)| idx >= s && idx < e);
                    let read_only = doc.read_only;
                    let sel_anchor = doc
                        .buffer
                        .selection()
                        .map(|(s, _)| s)
                        .unwrap_or_else(|| doc.buffer.caret());
                    if alt {
                        let (line, col) = hit_line_col_virtual(
                            ui,
                            pos,
                            &self.state.tabs.active().buffer,
                            self.scroll_line,
                            &visible_lines,
                        );
                        self.sel_text_drag = None;
                        self.rect_drag = true;
                        self.rect_drag_anchor = Some((line, col));
                        self.drag_anchor = None;
                        self.state
                            .tabs
                            .active_mut()
                            .set_rect_selection_cols(line, col, line, col);
                        self.state.status = "Column select (Alt+drag)".into();
                    } else if ctrl_cmd && !shift {
                        let (line, col) = hit_line_col_virtual(
                            ui,
                            pos,
                            &self.state.tabs.active().buffer,
                            self.scroll_line,
                            &visible_lines,
                        );
                        self.sel_text_drag = None;
                        self.rect_drag = false;
                        self.rect_drag_anchor = None;
                        self.drag_anchor = None;
                        self.state
                            .tabs
                            .active_mut()
                            .add_caret_at_line_col(line, col);
                        let n = self.state.tabs.active().multi_sels.len();
                        self.state.status = if n >= 2 {
                            format!("Multi-caret: {n} carets (Ctrl/Cmd+click)")
                        } else {
                            "Multi-caret: click cleared extras".into()
                        };
                    } else if !shift && inside_sel && !read_only {
                        self.state.tabs.active_mut().clear_multi_sels();
                        self.sel_text_drag = Some(SelTextDrag {
                            tab,
                            drop_tab: tab,
                            drop_at: idx,
                            drop_bar: SelDropBar::None,
                        });
                        self.drag_anchor = None;
                        self.rect_drag = false;
                        self.rect_drag_anchor = None;
                    } else if shift {
                        let (line, col) = hit_line_col_virtual(
                            ui,
                            pos,
                            &self.state.tabs.active().buffer,
                            self.scroll_line,
                            &visible_lines,
                        );
                        self.sel_text_drag = None;
                        self.rect_drag = false;
                        self.rect_drag_anchor = None;
                        self.drag_anchor = Some(sel_anchor);
                        self.state
                            .tabs
                            .active_mut()
                            .set_stream_selection_to_line_col(sel_anchor, line, col);
                    } else {
                        let (line, col) = hit_line_col_virtual(
                            ui,
                            pos,
                            &self.state.tabs.active().buffer,
                            self.scroll_line,
                            &visible_lines,
                        );
                        self.sel_text_drag = None;
                        self.rect_drag = false;
                        self.rect_drag_anchor = None;
                        self.state
                            .tabs
                            .active_mut()
                            .set_caret_at_line_col(line, col);
                        let caret_idx = self.state.tabs.active().buffer.caret();
                        self.drag_anchor = Some(caret_idx);
                    }
                    self.follow_caret = false;
                }
            } else if response.dragged() {
                if let Some(pos) = response.interact_pointer_pos() {
                    let idx = hit_index(
                        ui,
                        pos,
                        &self.state.tabs.active().buffer,
                        self.scroll_line,
                        &visible_lines,
                    );
                    if let Some(drag) = self.sel_text_drag.as_mut() {
                        if rect.contains(pos) {
                            drag.drop_bar = SelDropBar::None;
                            drag.drop_tab = self.state.tabs.active_index();
                            drag.drop_at = idx;
                            let copy = ui.input(|i| i.modifiers.ctrl || i.modifiers.command);
                            ui.ctx().set_cursor_icon(if copy {
                                CursorIcon::Copy
                            } else {
                                CursorIcon::Grabbing
                            });
                        }
                    } else if self.rect_drag {
                        if let Some((al, ac)) = self.rect_drag_anchor {
                            let (line, col) = hit_line_col_virtual(
                                ui,
                                pos,
                                &self.state.tabs.active().buffer,
                                self.scroll_line,
                                &visible_lines,
                            );
                            self.state
                                .tabs
                                .active_mut()
                                .set_rect_selection_cols(al, ac, line, col);
                            self.follow_caret = false;
                        }
                    } else if let Some(anchor) = self.drag_anchor {
                        let (line, col) = hit_line_col_virtual(
                            ui,
                            pos,
                            &self.state.tabs.active().buffer,
                            self.scroll_line,
                            &visible_lines,
                        );
                        self.state
                            .tabs
                            .active_mut()
                            .set_stream_selection_to_line_col(anchor, line, col);
                        self.follow_caret = false;
                    }
                }
            } else if response.clicked() {
                if let Some(pos) = response.interact_pointer_pos() {
                    let (shift, ctrl_cmd) =
                        ui.input(|i| (i.modifiers.shift, i.modifiers.ctrl || i.modifiers.command));
                    if shift {
                        let (line, col) = hit_line_col_virtual(
                            ui,
                            pos,
                            &self.state.tabs.active().buffer,
                            self.scroll_line,
                            &visible_lines,
                        );
                        let anchor = self
                            .state
                            .tabs
                            .active()
                            .buffer
                            .selection()
                            .map(|(s, _)| s)
                            .unwrap_or_else(|| self.state.tabs.active().buffer.caret());
                        self.state
                            .tabs
                            .active_mut()
                            .set_stream_selection_to_line_col(anchor, line, col);
                    } else if ctrl_cmd {
                        // drag_started already added on mouse-down; ignore mouse-up
                        // so we do not toggle the same caret twice.
                    } else {
                        let (line, col) = hit_line_col_virtual(
                            ui,
                            pos,
                            &self.state.tabs.active().buffer,
                            self.scroll_line,
                            &visible_lines,
                        );
                        self.state
                            .tabs
                            .active_mut()
                            .set_caret_at_line_col(line, col);
                        if self.compare_on {
                            self.sync_compare_other_to_caret_hunk(true);
                        }
                    }
                    self.drag_anchor = None;
                    self.rect_drag = false;
                    self.rect_drag_anchor = None;
                    self.sel_text_drag = None;
                    self.follow_caret = false;
                }
            }
            // Dual-view cross-pane: when drag started on the other pane, still
            // claim the drop target while the pointer is over this rect.
            if self.sel_text_drag.is_some() && ui.input(|i| i.pointer.primary_down()) {
                if let Some(pos) = ui.input(|i| i.pointer.latest_pos()) {
                    if rect.contains(pos) {
                        let idx = hit_index(
                            ui,
                            pos,
                            &self.state.tabs.active().buffer,
                            self.scroll_line,
                            &visible_lines,
                        );
                        let primary_tab = self.state.tabs.active_index();
                        if let Some(drag) = self.sel_text_drag.as_mut() {
                            drag.drop_bar = SelDropBar::None;
                            drag.drop_tab = primary_tab;
                            drag.drop_at = idx;
                        }
                        let copy = ui.input(|i| i.modifiers.ctrl || i.modifiers.command);
                        ui.ctx().set_cursor_icon(if copy {
                            CursorIcon::Copy
                        } else {
                            CursorIcon::Grabbing
                        });
                    }
                }
            }
            if ui.input(|i| i.pointer.any_released()) {
                if self.sel_text_drag.is_some() {
                    let copy = ui.input(|i| i.modifiers.ctrl || i.modifiers.command);
                    self.finish_sel_text_drag(copy);
                }
                self.drag_anchor = None;
                self.rect_drag = false;
                self.rect_drag_anchor = None;
                if self
                    .scrollbar_drag
                    .as_ref()
                    .is_some_and(|d| d.pane == EditorPane::Primary)
                {
                    self.scrollbar_drag = None;
                }
            }

            // Text input (arrows / typing may request caret follow)
            if response.has_focus()
                && self.focused_pane == EditorPane::Primary
                && !self.state.find_open
                && !self.show_replace
            {
                let tab = self.state.tabs.active_index();
                if self.handle_editor_input(ui, tab) {
                    self.follow_caret = true;
                    // Arrow / keyboard caret on a change line parks the other pane (same as click).
                    if self.compare_on
                        && (tab == self.compare_left_tab || tab == self.compare_right_tab)
                    {
                        self.sync_compare_other_to_caret_hunk(tab == self.compare_left_tab);
                    }
                }
            }

            // Only keep caret in view after caret motion — not after wheel scroll.
            if self.follow_caret {
                let caret_line = self
                    .state
                    .tabs
                    .active()
                    .buffer
                    .char_to_line(self.state.tabs.active().buffer.caret());
                let caret_row = display_row_for(&visible_lines, caret_line) as f32;
                if caret_row < self.scroll_line {
                    self.scroll_line = caret_row;
                } else if caret_row >= self.scroll_line + visible_rows as f32 {
                    self.scroll_line = caret_row - visible_rows as f32 + 1.0;
                }
                self.scroll_line = self.scroll_line.clamp(0.0, max_scroll);
                self.follow_caret = false;
            }

            let first_row = self.scroll_line.floor() as usize;
            let visible = visible_rows + 2;
            let last_row = (first_row + visible).min(display_count);

            let painter = ui.painter_at(rect);
            let theme = self.current_theme();
            painter.rect_filled(rect, 0.0, theme.editor_bg);
            // Gutter band + hairline so numbers stay separate from text.
            painter.rect_filled(
                Rect::from_min_max(
                    Pos2::new(rect.left(), rect.top()),
                    Pos2::new(gutter_right, rect.bottom()),
                ),
                0.0,
                theme.gutter_bg,
            );
            painter.vline(
                gutter_right,
                rect.y_range(),
                egui::Stroke::new(1.0_f32, theme.gutter_line),
            );

            let hl = &self.state.highlight_cache;
            let lang = self.state.tabs.active().language.clone();
            let bookmarks = self.state.tabs.active().bookmarks.clone();
            let changed_unsaved = self.state.tabs.active().changed_unsaved.clone();
            let changed_saved = self.state.tabs.active().changed_saved.clone();
            let style_marks = self.state.tabs.active().style_marks.clone();
            let hidden_lines = self.state.tabs.active().hidden_lines.clone();
            let fold_regions =
                crate::fold::compute_fold_regions(lang.as_str(), &self.state.tabs.active().buffer);
            let ln_right = if show_fold {
                fold_left - 2.0
            } else {
                gutter_right - 6.0
            };

            for row in first_row..last_row {
                let Some(&line_idx) = visible_lines.get(row) else {
                    break;
                };
                let y = rect.top() + (row as f32 - self.scroll_line) * row_height;
                let line_rect = Rect::from_min_size(
                    Pos2::new(rect.left(), y),
                    Vec2::new(rect.width(), row_height),
                );

                // Style-mark soft wash (first matching slot wins for paint).
                for (slot, marks) in style_marks.iter().enumerate() {
                    if marks.contains(&line_idx) {
                        painter.rect_filled(
                            Rect::from_min_max(
                                Pos2::new(text_left, y),
                                Pos2::new(rect.right(), y + row_height),
                            ),
                            0.0,
                            style_mark_bg((slot as u8) + 1),
                        );
                        break;
                    }
                }

                // 2-way compare wash (primary shows left side while comparing).
                if self.compare_on {
                    if let Some(kind) = self.compare_left_tags.get(line_idx) {
                        if let Some(bg) = crate::diff::line_kind_bg(*kind) {
                            painter.rect_filled(
                                Rect::from_min_max(
                                    Pos2::new(text_left, y),
                                    Pos2::new(rect.right(), y + row_height),
                                ),
                                0.0,
                                bg,
                            );
                        }
                    }
                    if self.state.settings.compare_hide_equal {
                        if let Some(&prev) = row.checked_sub(1).and_then(|r| visible_lines.get(r)) {
                            if let Some(skipped) = crate::diff::compare_visible_gap(prev, line_idx)
                            {
                                paint_compare_hide_gap(
                                    &painter,
                                    &font_id,
                                    text_left,
                                    rect.right(),
                                    y,
                                    skipped,
                                    theme.line_number_fg,
                                );
                            }
                        }
                    }
                }

                // Bookmark tick in the gutter.
                if bookmarks.contains(&line_idx) {
                    painter.rect_filled(
                        Rect::from_min_max(
                            Pos2::new(rect.left() + 4.0, y + 3.0),
                            Pos2::new(rect.left() + 10.0, y + row_height - 3.0),
                        ),
                        1.0,
                        Color32::from_rgb(80, 180, 220),
                    );
                }

                // Change-history bar in the gutter (amber = unsaved, green = saved).
                if changed_unsaved.contains(&line_idx) {
                    let (join_above, join_below) =
                        change_history_joins(line_idx, false, &changed_unsaved, &changed_saved);
                    paint_change_history_bar(
                        &painter,
                        rect.left(),
                        y,
                        row_height,
                        false,
                        join_above,
                        join_below,
                    );
                    painter.rect_filled(
                        Rect::from_min_max(
                            Pos2::new(text_left, y),
                            Pos2::new(rect.right(), y + row_height),
                        ),
                        0.0,
                        change_history_wash(false),
                    );
                } else if changed_saved.contains(&line_idx) {
                    let (join_above, join_below) =
                        change_history_joins(line_idx, true, &changed_unsaved, &changed_saved);
                    paint_change_history_bar(
                        &painter,
                        rect.left(),
                        y,
                        row_height,
                        true,
                        join_above,
                        join_below,
                    );
                    painter.rect_filled(
                        Rect::from_min_max(
                            Pos2::new(text_left, y),
                            Pos2::new(rect.right(), y + row_height),
                        ),
                        0.0,
                        change_history_wash(true),
                    );
                }

                // Line number — right-aligned inside the gutter (left of fold margin).
                if show_ln {
                    painter.text(
                        Pos2::new(ln_right, y),
                        egui::Align2::RIGHT_TOP,
                        format!("{}", line_idx + 1),
                        font_id.clone(),
                        theme.line_number_fg,
                    );
                }

                // Fold margin marker (− open / + folded).
                if show_fold {
                    if let Some(region) = crate::fold::region_at_header(&fold_regions, line_idx) {
                        let folded = crate::fold::is_folded(&hidden_lines, &region);
                        paint_fold_marker(
                            &painter,
                            &font_id,
                            fold_left,
                            fold_w,
                            y,
                            row_height,
                            folded,
                            theme.line_number_fg,
                        );
                    }
                }

                let line_start = self.state.tabs.active().buffer.line_to_char(line_idx);
                let raw = self.state.tabs.active().buffer.line(line_idx);
                let line_text = raw.trim_end_matches(['\n', '\r']);

                if self.compare_on {
                    if let Some(kind) = self.compare_left_tags.get(line_idx) {
                        if let Some(bg) = crate::diff::line_kind_inline_bg(*kind) {
                            if let Some(spans) = self.compare_left_inline.get(line_idx) {
                                paint_inline_compare_spans(
                                    &painter,
                                    ui,
                                    &font_id,
                                    Rect::from_min_size(
                                        Pos2::new(text_left, y),
                                        Vec2::new(rect.width(), row_height),
                                    ),
                                    line_text,
                                    spans,
                                    bg,
                                );
                            }
                        }
                    }
                }

                // Selection highlight on line (rect / stream virtual cols may extend past EOL)
                let primary_sel = self.state.tabs.active().buffer.selection();
                let multi = self.state.tabs.active().multi_sels.clone();
                let rect_cols = self.state.tabs.active().rect_cols;
                let caret_for_sel = self.state.tabs.active().buffer.caret();
                let virtual_caret_for_sel = self.state.tabs.active().virtual_caret_col;
                let line_end = line_start + line_text.chars().count();
                let line_in_rect = multi.iter().any(|&(s, e)| {
                    let c = s.min(e);
                    c >= line_start && c <= line_end
                });
                if let Some((col_lo, col_hi)) = rect_cols.filter(|_| line_in_rect) {
                    if col_lo < col_hi {
                        let x0 = text_left + x_for_col(ui, &font_id, line_text, col_lo);
                        let x1 = text_left + x_for_col(ui, &font_id, line_text, col_hi);
                        painter.rect_filled(
                            Rect::from_min_max(
                                Pos2::new(x0, y),
                                Pos2::new(x1.max(x0 + 2.0), y + row_height),
                            ),
                            0.0,
                            theme.selection_bg,
                        );
                    }
                } else if let Some((sel_s, sel_e)) = primary_sel {
                    if sel_s < line_end && sel_e > line_start {
                        let local_s = sel_s
                            .saturating_sub(line_start)
                            .min(line_text.chars().count());
                        let mut local_e = sel_e
                            .saturating_sub(line_start)
                            .min(line_text.chars().count());
                        // Stream select: extend wash past EOL when caret end is virtual.
                        if sel_e == caret_for_sel && caret_for_sel == line_end {
                            if let Some(vc) =
                                virtual_caret_for_sel.filter(|&vc| vc > line_text.chars().count())
                            {
                                local_e = vc;
                            }
                        }
                        let x0 = text_left + x_for_col(ui, &font_id, line_text, local_s);
                        let x1 = text_left + x_for_col(ui, &font_id, line_text, local_e);
                        painter.rect_filled(
                            Rect::from_min_max(
                                Pos2::new(x0, y),
                                Pos2::new(x1.max(x0 + 2.0), y + row_height),
                            ),
                            0.0,
                            theme.selection_bg,
                        );
                    }
                }
                // Extra multi-caret / rect ranges (skip primary to avoid double paint)
                if let Some((col_lo, col_hi)) = rect_cols.filter(|_| line_in_rect) {
                    if col_lo == col_hi {
                        let cx = text_left + x_for_col(ui, &font_id, line_text, col_lo);
                        painter.line_segment(
                            [Pos2::new(cx, y), Pos2::new(cx, y + row_height - 1.0)],
                            egui::Stroke::new(1.0_f32, theme.caret_fg),
                        );
                    }
                } else {
                    for &(anchor, caret_end) in &multi {
                        let sel_s = anchor.min(caret_end);
                        let sel_e = anchor.max(caret_end);
                        if primary_sel == Some((sel_s, sel_e)) {
                            continue;
                        }
                        if sel_s == sel_e {
                            // Zero-width caret mark
                            if sel_s >= line_start && sel_s <= line_end {
                                let col = sel_s - line_start;
                                let prefix: String = line_text.chars().take(col).collect();
                                let cx = text_left + text_width(ui, &font_id, &prefix);
                                painter.line_segment(
                                    [Pos2::new(cx, y), Pos2::new(cx, y + row_height - 1.0)],
                                    egui::Stroke::new(1.0_f32, theme.caret_fg),
                                );
                            }
                            continue;
                        }
                        if sel_s < line_end && sel_e > line_start {
                            let local_s = sel_s
                                .saturating_sub(line_start)
                                .min(line_text.chars().count());
                            let local_e = sel_e
                                .saturating_sub(line_start)
                                .min(line_text.chars().count());
                            let x0 = text_left
                                + text_width(
                                    ui,
                                    &font_id,
                                    &line_text.chars().take(local_s).collect::<String>(),
                                );
                            let x1 = text_left
                                + text_width(
                                    ui,
                                    &font_id,
                                    &line_text.chars().take(local_e).collect::<String>(),
                                );
                            painter.rect_filled(
                                Rect::from_min_max(
                                    Pos2::new(x0, y),
                                    Pos2::new(x1.max(x0 + 2.0), y + row_height),
                                ),
                                0.0,
                                theme.selection_bg,
                            );
                        }
                    }
                }

                paint_line_text(
                    &painter,
                    ui,
                    &font_id,
                    text_left,
                    y,
                    line_text,
                    line_start,
                    hl,
                    &lang,
                    &theme,
                    crate::commands::edit::text_is_rtl(),
                );

                // Whitespace / NPC / EOL overlays
                let ws_color = theme.whitespace_fg;
                if self.state.show_whitespace || self.state.show_npc {
                    for (col, ch) in line_text.chars().enumerate() {
                        let x = text_left
                            + text_width(
                                ui,
                                &font_id,
                                &line_text.chars().take(col).collect::<String>(),
                            );
                        let mark = if self.state.show_whitespace && ch == ' ' {
                            Some("·")
                        } else if self.state.show_whitespace && ch == '\t' {
                            Some("→")
                        } else if self.state.show_npc && ch.is_control() {
                            Some("·")
                        } else {
                            None
                        };
                        if let Some(m) = mark {
                            painter.text(
                                Pos2::new(x, y),
                                egui::Align2::LEFT_TOP,
                                m,
                                font_id.clone(),
                                ws_color,
                            );
                        }
                    }
                }
                if self.state.show_eol {
                    let x = text_left + text_width(ui, &font_id, line_text);
                    painter.text(
                        Pos2::new(x, y),
                        egui::Align2::LEFT_TOP,
                        "¶",
                        font_id.clone(),
                        ws_color,
                    );
                }
                if self.state.show_indent_guide {
                    let avail = (rect.right() - text_left).max(0.0);
                    let col_w = text_width(ui, &font_id, " ");
                    if col_w > 0.0 {
                        let tab_w = self.state.settings.tab_width.max(1) as f32;
                        let mut gx = text_left + col_w * tab_w;
                        while gx < text_left + avail {
                            painter.line_segment(
                                [Pos2::new(gx, y), Pos2::new(gx, y + row_height)],
                                egui::Stroke::new(1.0_f32, theme.indent_guide),
                            );
                            gx += col_w * tab_w;
                        }
                    }
                }
                if self.state.word_wrap && self.state.show_wrap_symbol {
                    let max_w = (rect.right() - text_left - 8.0).max(40.0);
                    if text_width(ui, &font_id, line_text) > max_w {
                        painter.text(
                            Pos2::new(rect.right() - 14.0, y),
                            egui::Align2::LEFT_TOP,
                            "↩",
                            font_id.clone(),
                            ws_color,
                        );
                    }
                }

                // Caret (rect zero-width already painted above; wide rect uses virtual col_hi)
                let caret = self.state.tabs.active().buffer.caret();
                let virtual_caret_col = self.state.tabs.active().virtual_caret_col;
                let blink_on = if self.state.settings.caret_blink {
                    ctx.request_repaint_after(std::time::Duration::from_millis(500));
                    ((ctx.input(|i| i.time) * 2.0_f64) as i64).rem_euclid(2) == 0
                } else {
                    true
                };
                if blink_on {
                    if let Some((col_lo, col_hi)) = rect_cols.filter(|_| line_in_rect) {
                        if col_lo < col_hi && caret >= line_start && caret <= line_end {
                            let cx = text_left + x_for_col(ui, &font_id, line_text, col_hi);
                            painter.line_segment(
                                [Pos2::new(cx, y), Pos2::new(cx, y + row_height - 1.0)],
                                egui::Stroke::new(1.0_f32, theme.caret_fg),
                            );
                        }
                    } else if caret >= line_start && caret <= line_end {
                        let col = virtual_caret_col
                            .filter(|&vc| vc > line_text.chars().count() && caret == line_end)
                            .unwrap_or(caret - line_start);
                        let cx = text_left + x_for_col(ui, &font_id, line_text, col);
                        painter.line_segment(
                            [Pos2::new(cx, y), Pos2::new(cx, y + row_height - 1.0)],
                            egui::Stroke::new(1.0_f32, theme.caret_fg),
                        );
                    }
                }

                // Drop caret while dragging selected text (source or other-view drop).
                if let Some(drag) = self.sel_text_drag.as_ref() {
                    if drag.drop_bar == SelDropBar::None
                        && drag.drop_tab == self.state.tabs.active_index()
                        && drag.drop_at >= line_start
                        && drag.drop_at <= line_end
                    {
                        let col = drag.drop_at - line_start;
                        let prefix: String = line_text.chars().take(col).collect();
                        let cx = text_left + text_width(ui, &font_id, &prefix);
                        painter.line_segment(
                            [Pos2::new(cx, y), Pos2::new(cx, y + row_height - 1.0)],
                            egui::Stroke::new(2.0_f32, Color32::from_rgb(220, 140, 40)),
                        );
                    }
                }

                let _ = line_rect;
            }

            // Scrollbar thumb (click / drag handled above).
            if let Some(layout) = editor_scrollbar_layout(
                rect,
                self.scroll_line,
                max_scroll,
                visible_rows,
                display_count,
            ) {
                paint_editor_scrollbar(&painter, &layout, theme.gutter_line);
            }
        });
    }

    fn persist_font_size(&mut self) {
        self.state.settings.font_size = self.font_size;
        self.state.settings.save();
    }

    fn clamp_other_view_tab(&mut self) {
        let n = self.state.tabs.len();
        if n == 0 {
            self.other_view_tab = 0;
            self.compare_partner_tab = None;
            return;
        }
        if self.other_view_tab >= n {
            self.other_view_tab = n - 1;
        }
        if let Some(p) = self.compare_partner_tab {
            if p >= n {
                self.compare_partner_tab = None;
            }
        }
    }

    /// Tab that receives typing / undo for the focused pane.
    fn focused_edit_tab(&self) -> usize {
        if self.dual_view && self.focused_pane == EditorPane::Secondary {
            self.other_view_tab
        } else {
            self.state.tabs.active_index()
        }
    }

    /// Run a menu command. Edit/Format IDs temporarily activate the focused dual-view tab.
    fn dispatch_menu_cmd(
        &mut self,
        cmd: &str,
        flags: &mut crate::commands::UiFlags,
    ) -> crate::commands::CmdResult {
        let retarget_menu =
            (cmd.starts_with("IDM_EDIT_") || cmd.starts_with("IDM_FORMAT_")) && self.dual_view;
        let focus = self.focused_edit_tab();
        let saved = self.state.tabs.active_index();
        let redirect = retarget_menu && focus != saved;
        if redirect {
            self.state.tabs.set_active(focus);
        }
        let result = crate::commands::dispatch(cmd, &mut self.state, flags);
        if redirect {
            let n = self.state.tabs.len();
            if n > 0 && saved < n {
                self.state.tabs.set_active(saved);
                self.state.highlight_dirty = true;
            }
            self.clamp_other_view_tab();
        }
        result
    }

    fn follow_focused_caret(&mut self) {
        if self.focused_pane == EditorPane::Secondary && self.dual_view {
            self.follow_caret_other = true;
            self.follow_caret = false;
        } else {
            self.follow_caret = true;
            self.follow_caret_other = false;
        }
    }

    fn ensure_other_view_tab(&mut self) {
        self.clamp_other_view_tab();
        let n = self.state.tabs.len();
        if n <= 1 {
            return;
        }
        let active = self.state.tabs.active_index();
        if self.other_view_tab == active {
            self.other_view_tab = (active + 1) % n;
        }
    }

    /// Toggle keyboard focus between primary and secondary panes (menu Focus on Another View).
    fn focus_other_view_now(&mut self) {
        self.dual_view = true;
        self.ensure_other_view_tab();
        let a = self.state.tabs.active_index();
        let b = self.other_view_tab;
        if a == b {
            self.state.status = "Other view shows the same tab".into();
            return;
        }
        self.focused_pane = match self.focused_pane {
            EditorPane::Primary => EditorPane::Secondary,
            EditorPane::Secondary => EditorPane::Primary,
        };
        let tab = self.focused_edit_tab();
        let title = self
            .state
            .tabs
            .get(tab)
            .map(|d| d.title.clone())
            .unwrap_or_else(|| "?".into());
        let side = match self.focused_pane {
            EditorPane::Primary => "primary",
            EditorPane::Secondary => "other",
        };
        if self.compare_on {
            let pane = match self.focused_pane {
                EditorPane::Primary => "L",
                EditorPane::Secondary => "R",
            };
            self.state.status = format!("Focused {side} view ({pane}): “{title}”");
        } else {
            self.state.status = format!("Focused {side} view: “{title}”");
        }
    }

    /// Swap the active tab with the secondary pane (header Switch / Shift+focus chord).
    fn switch_other_view_now(&mut self) {
        self.dual_view = true;
        self.ensure_other_view_tab();
        let a = self.state.tabs.active_index();
        let b = self.other_view_tab;
        if a == b {
            self.state.status = "Other view shows the same tab".into();
            return;
        }
        self.state.tabs.set_active(b);
        self.other_view_tab = a;
        self.focused_pane = EditorPane::Primary;
        self.state.highlight_dirty = true;
        std::mem::swap(&mut self.scroll_line, &mut self.scroll_line_other);
        if self.compare_on {
            std::mem::swap(&mut self.compare_left_tab, &mut self.compare_right_tab);
            std::mem::swap(&mut self.compare_left_tags, &mut self.compare_right_tags);
            std::mem::swap(
                &mut self.compare_left_inline,
                &mut self.compare_right_inline,
            );
            std::mem::swap(
                &mut self.compare_hide_revealed_left,
                &mut self.compare_hide_revealed_right,
            );
        }
        let title = self.state.tabs.active().title.clone();
        self.state.status = format!("Swapped tabs — primary: “{title}”");
    }

    /// Remap dual-view / compare indices after tabs closed this frame.
    /// Closing a non-compared tab between the pair keeps Compare alive.
    fn apply_closed_tab_indices(&mut self) {
        let closed = self.state.take_closed_tabs();
        for idx in closed {
            self.after_tab_closed(idx);
        }
    }

    fn after_tab_closed(&mut self, closed: usize) {
        self.state.on_tab_closed_highlight_other(closed);
        match self.compare_partner_tab {
            Some(p) if p == closed => self.compare_partner_tab = None,
            Some(p) => self.compare_partner_tab = index_after_tab_close(p, closed),
            None => {}
        }
        if let Some(other) = index_after_tab_close(self.other_view_tab, closed) {
            self.other_view_tab = other;
        } else {
            self.other_view_tab = 0;
        }
        self.last_primary_tab = self
            .last_primary_tab
            .and_then(|i| index_after_tab_close(i, closed));
        if !self.compare_on {
            return;
        }
        let Some(left) = index_after_tab_close(self.compare_left_tab, closed) else {
            self.clear_compare();
            return;
        };
        let Some(right) = index_after_tab_close(self.compare_right_tab, closed) else {
            self.clear_compare();
            return;
        };
        self.compare_left_tab = left;
        self.compare_right_tab = right;
    }

    /// Keep compare panes on the compared pair (left = primary, right = other).
    fn sync_compare_panes(&mut self) {
        if !self.compare_on {
            return;
        }
        let n = self.state.tabs.len();
        if n == 0 {
            self.clear_compare();
            return;
        }
        if self.compare_left_tab >= n || self.compare_right_tab >= n {
            self.clear_compare();
            return;
        }
        if self.compare_left_tab == self.compare_right_tab {
            self.clear_compare();
            return;
        }
        self.dual_view = true;
        self.other_view_tab = self.compare_right_tab;
        if self.state.tabs.active_index() != self.compare_left_tab {
            self.state.tabs.set_active(self.compare_left_tab);
            self.state.highlight_dirty = true;
        }
    }

    fn apply_dual_view_flags(&mut self, flags: &mut crate::commands::UiFlags) {
        if flags.sync_scroll_h_toggle {
            self.sync_scroll_h = !self.sync_scroll_h;
            self.state.status = format!(
                "Sync H scroll: {} (dual view — shared line scroll)",
                if self.sync_scroll_h { "on" } else { "off" }
            );
        }
        if flags.sync_scroll_v_toggle {
            self.sync_scroll_v = !self.sync_scroll_v;
            self.state.status = format!(
                "Sync V scroll: {} (dual view)",
                if self.sync_scroll_v { "on" } else { "off" }
            );
        }
        if flags.zoom_sync_toggle {
            self.zoom_sync = !self.zoom_sync;
            self.state.settings.zoom_sync = self.zoom_sync;
            self.state.settings.save();
            self.state.status = format!(
                "Zoom sync: {} (both panes share font size)",
                if self.zoom_sync { "on" } else { "off" }
            );
        }
        if let Some(on) = flags.dual_view {
            self.dual_view = on;
            if on {
                self.ensure_other_view_tab();
            } else {
                self.focused_pane = EditorPane::Primary;
            }
        }
        if let Some(idx) = flags.other_view_tab {
            self.other_view_tab = idx;
            self.dual_view = true;
            self.clamp_other_view_tab();
        }
        if flags.assign_other_view {
            self.other_view_tab = self.state.tabs.active_index();
            self.dual_view = true;
            let n = self.state.tabs.len();
            if n > 1 {
                let next = (self.other_view_tab + 1) % n;
                self.state.tabs.set_active(next);
                self.state.highlight_dirty = true;
            }
        }
        if flags.switch_other_view {
            self.focus_other_view_now();
        }
        if flags.clear_compare {
            self.clear_compare();
        }
        if flags.start_compare {
            self.start_compare();
        }
        if flags.compare_to_saved {
            self.compare_to_saved();
        }
        if flags.swap_compare {
            self.swap_compare_sides();
        }
        if let Some(nav) = flags.compare_nav {
            self.navigate_compare_hunk(nav);
        }
        if let Some(toggle) = flags.compare_ignore_toggle {
            self.toggle_compare_ignore(toggle);
        }
        if flags.compare_hide_equal_toggle {
            self.toggle_compare_hide_equal();
        }
        if let Some(delta) = flags.compare_hide_equal_context_delta {
            self.adjust_compare_hide_equal_context(delta);
        }
        if flags.compare_expand_hidden_equal_at_caret {
            self.expand_compare_hide_equal_at_caret();
        }
        if flags.compare_collapse_hidden_equal_at_caret {
            self.collapse_compare_hide_equal_at_caret();
        }
        if let Some(nav) = flags.compare_hide_gap_nav {
            self.navigate_compare_hide_gap(nav);
        }
        if flags.compare_expand_hidden_equal {
            self.expand_all_compare_hide_equal();
        }
        if flags.compare_collapse_hidden_equal {
            self.collapse_all_compare_hide_equal();
        }
        if flags.compare_bookmark_diffs {
            self.bookmark_compare_differences();
        }
        if flags.compare_clear_diff_bookmarks {
            self.clear_compare_difference_bookmarks();
        }
        if flags.copy_compare_diff {
            self.copy_compare_diff(flags);
        }
        if flags.open_compare_diff {
            self.open_compare_diff_tab();
        }
        if flags.copy_compare_summary {
            self.copy_compare_summary(flags);
        }
        if flags.open_compare_summary {
            self.open_compare_summary_tab();
        }
        if flags.copy_compare_hunk {
            self.copy_compare_hunk(flags);
        }
        if flags.open_compare_hunk {
            self.open_compare_hunk_tab();
        }
        if flags.apply_compare_hunk {
            self.apply_compare_hunk_from_other();
        }
        if flags.apply_compare_hunk_to_other {
            self.apply_compare_hunk_to_other();
        }
        if flags.apply_all_compare_hunks {
            self.apply_all_compare_hunks_from_other();
        }
        if flags.apply_all_compare_hunks_to_other {
            self.apply_all_compare_hunks_to_other();
        }
    }

    /// Toggle ignore-whitespace / ignore-case / ignore-blank from View menu; persist and re-diff.
    fn toggle_compare_ignore(&mut self, toggle: crate::commands::CompareIgnoreToggle) {
        match toggle {
            crate::commands::CompareIgnoreToggle::Whitespace => {
                self.state.settings.compare_ignore_ws = !self.state.settings.compare_ignore_ws;
            }
            crate::commands::CompareIgnoreToggle::Case => {
                self.state.settings.compare_ignore_case = !self.state.settings.compare_ignore_case;
            }
            crate::commands::CompareIgnoreToggle::BlankLines => {
                self.state.settings.compare_ignore_blank =
                    !self.state.settings.compare_ignore_blank;
            }
        }
        self.state.settings.save();
        let ignore = CompareIgnoreBits {
            ws: self.state.settings.compare_ignore_ws,
            case: self.state.settings.compare_ignore_case,
            blank: self.state.settings.compare_ignore_blank,
        };
        if self.compare_on {
            self.refresh_compare_after_ignore_change();
        } else {
            let which = match toggle {
                crate::commands::CompareIgnoreToggle::Whitespace => "Ignore whitespace",
                crate::commands::CompareIgnoreToggle::Case => "Ignore case",
                crate::commands::CompareIgnoreToggle::BlankLines => "Ignore blank lines",
            };
            let on = match toggle {
                crate::commands::CompareIgnoreToggle::Whitespace => ignore.ws,
                crate::commands::CompareIgnoreToggle::Case => ignore.case,
                crate::commands::CompareIgnoreToggle::BlankLines => ignore.blank,
            };
            self.state.status = format!(
                "{which}: {}{}",
                if on { "on" } else { "off" },
                compare_ignore_status_bit(ignore)
            );
        }
    }

    /// Re-diff the active pair after ignore settings already changed (View or Preferences).
    /// Parks and selects the first change hunk; updates pair status with `· at L|R …`.
    fn refresh_compare_after_ignore_change(&mut self) {
        if !self.compare_on {
            return;
        }
        let ignore = CompareIgnoreBits {
            ws: self.state.settings.compare_ignore_ws,
            case: self.state.settings.compare_ignore_case,
            blank: self.state.settings.compare_ignore_blank,
        };
        let hide_equal = self.state.settings.compare_hide_equal;
        // Refresh immediately so the toggle is visible without waiting for debounce.
        self.state.compare_stale = false;
        self.compare_refresh_at = None;
        let left = self.compare_left_tab;
        let right = self.compare_right_tab;
        let Some((lt, rt, _, _)) = self.compute_compare_tags(left, right) else {
            return;
        };
        self.compare_left_tags = lt;
        self.compare_right_tags = rt;
        crate::diff::prune_compare_hide_revealed(
            &mut self.compare_hide_revealed_left,
            &self.compare_left_tags,
            self.state.settings.compare_hide_equal_context_lines(),
        );
        crate::diff::prune_compare_hide_revealed(
            &mut self.compare_hide_revealed_right,
            &self.compare_right_tags,
            self.state.settings.compare_hide_equal_context_lines(),
        );
        let lname = self
            .state
            .tabs
            .get(left)
            .map(|d| d.title.clone())
            .unwrap_or_else(|| "left".into());
        let rname = self
            .state
            .tabs
            .get(right)
            .map(|d| d.title.clone())
            .unwrap_or_else(|| "right".into());
        let hide = compare_hide_opt(
            hide_equal,
            &self.compare_left_tags,
            &self.compare_right_tags,
            &self.compare_hide_revealed_left,
            &self.compare_hide_revealed_right,
            self.state.settings.compare_hide_equal_context_lines(),
        );
        let counts =
            compare_pair_counts_from_tags(&self.compare_left_tags, &self.compare_right_tags);
        let hunk_n = counts.hunk_n;
        // Ignore toggles reshuffle hunks — re-park like Compare start.
        if hunk_n > 0 {
            self.park_compare_hunk_ordinal(1);
            self.select_compare_hunk_on_pane(true, 1);
            self.select_compare_hunk_on_pane(false, 1);
        }
        let mut status = compare_pair_status(
            &lname,
            &rname,
            counts,
            ignore,
            CompareHideStatus {
                hidden: hide,
                context: self.state.settings.compare_hide_equal_context_lines(),
            },
            self.compare_sides_truncated(),
        );
        if hunk_n > 0 {
            let lr = self.compare_hunk_lr_label(1);
            let ordinal = self.compare_hunk_ordinal_bit(1, hunk_n);
            status.push_str(&compare_at_hunk_status_bit(&lr, &ordinal));
        }
        self.state.status = status;
        self.state.highlight_dirty = true;
    }

    /// Click a ···N hide-equal cue to reveal that collapsed Equal run on both panes.
    fn try_expand_compare_hide_gap_at(
        &mut self,
        pos: Pos2,
        rect: Rect,
        scroll_line: f32,
        row_height: f32,
        visible_lines: &[usize],
        left_pane: bool,
    ) -> bool {
        if !self.compare_on || !self.state.settings.compare_hide_equal {
            return false;
        }
        let Some(gap) =
            compare_hide_gap_at_pointer(pos, rect, scroll_line, row_height, visible_lines)
        else {
            return false;
        };
        self.expand_compare_hide_gap(gap, left_pane)
    }

    /// Reveal one hide-equal gap on the focused pane and its aligned partners.
    fn expand_compare_hide_gap(&mut self, gap: (usize, usize), left_pane: bool) -> bool {
        let n = if left_pane {
            crate::diff::reveal_compare_gap(&mut self.compare_hide_revealed_left, gap)
        } else {
            crate::diff::reveal_compare_gap(&mut self.compare_hide_revealed_right, gap)
        };
        if n == 0 {
            return false;
        }
        let partners = crate::diff::aligned_equal_partner_lines(
            &self.compare_left_tags,
            &self.compare_right_tags,
            gap,
            left_pane,
        );
        let n_other = if left_pane {
            crate::diff::reveal_compare_lines(&mut self.compare_hide_revealed_right, &partners)
        } else {
            crate::diff::reveal_compare_lines(&mut self.compare_hide_revealed_left, &partners)
        };
        let hide = compare_hide_opt(
            true,
            &self.compare_left_tags,
            &self.compare_right_tags,
            &self.compare_hide_revealed_left,
            &self.compare_hide_revealed_right,
            self.state.settings.compare_hide_equal_context_lines(),
        );
        let remain = hide.map(|(l, r)| l + r).unwrap_or(0);
        let both = if n_other > 0 { " both panes" } else { "" };
        let counts =
            compare_pair_counts_from_tags(&self.compare_left_tags, &self.compare_right_tags);
        self.state.status = compare_expand_gap_status(
            n,
            both,
            counts.del,
            counts.ins,
            counts.hunk_n,
            &counts.kind_bit,
            remain,
        );
        true
    }

    /// Jump to the next/previous collapsed Equal (···N) gap on the focused pane.
    fn navigate_compare_hide_gap(&mut self, nav: crate::commands::CompareHideGapNav) {
        if !self.compare_on {
            self.state.status = "Compare off — start Compare to navigate hidden equal lines".into();
            return;
        }
        if !self.state.settings.compare_hide_equal {
            self.state.status =
                "Hide Unchanged Lines is off — turn it on to navigate ···N gaps".into();
            return;
        }
        let left_pane = self.focused_pane == EditorPane::Primary || !self.dual_view;
        let tab = if left_pane {
            self.compare_left_tab
        } else {
            self.compare_right_tab
        };
        let Some(doc) = self.state.tabs.get(tab) else {
            return;
        };
        let caret_line = doc.buffer.char_to_line(doc.buffer.caret());
        let line_count = doc.buffer.line_count().max(1);
        let (tags, revealed) = if left_pane {
            (&self.compare_left_tags, &self.compare_hide_revealed_left)
        } else {
            (&self.compare_right_tags, &self.compare_hide_revealed_right)
        };
        let visible = visible_lines_with_compare_hide(
            line_count,
            &doc.hidden_lines,
            true,
            true,
            tags,
            revealed,
            self.state.settings.compare_hide_equal_context_lines(),
        );
        let gaps = crate::diff::list_compare_hide_gaps(&visible);
        let Some(gap) = (match nav {
            crate::commands::CompareHideGapNav::Next => {
                crate::diff::next_compare_hide_gap(caret_line, &gaps)
            }
            crate::commands::CompareHideGapNav::Prev => {
                crate::diff::prev_compare_hide_gap(caret_line, &gaps)
            }
            crate::commands::CompareHideGapNav::First => gaps.first().copied(),
            crate::commands::CompareHideGapNav::Last => gaps.last().copied(),
        }) else {
            self.state.status = "Compare: no hidden equal gaps".into();
            return;
        };
        let park = crate::diff::compare_hide_gap_park_line(gap);
        let n = gap.1 - gap.0 + 1;
        let (ord, total) = crate::diff::compare_hide_gap_ordinal(&gaps, gap).unwrap_or((1, 1));
        let wrapped = match nav {
            crate::commands::CompareHideGapNav::Next => {
                crate::diff::hunk_nav_wrapped(true, caret_line, park)
            }
            crate::commands::CompareHideGapNav::Prev => {
                crate::diff::hunk_nav_wrapped(false, caret_line, park)
            }
            crate::commands::CompareHideGapNav::First
            | crate::commands::CompareHideGapNav::Last => false,
        };
        if let Some(doc) = self.state.tabs.get_mut(tab) {
            let at = doc
                .buffer
                .line_to_char(park.min(doc.buffer.line_count().saturating_sub(1)));
            doc.buffer.set_caret(at);
        }
        if left_pane {
            self.follow_caret = true;
        } else {
            self.follow_caret_other = true;
        }
        self.sync_compare_other_to_equal_line(left_pane, park);
        let dir = match nav {
            crate::commands::CompareHideGapNav::Next => "Next",
            crate::commands::CompareHideGapNav::Prev => "Previous",
            crate::commands::CompareHideGapNav::First => "First",
            crate::commands::CompareHideGapNav::Last => "Last",
        };
        let counts =
            compare_pair_counts_from_tags(&self.compare_left_tags, &self.compare_right_tags);
        // Overwrite equal-park status with gap-nav ordinal + pair −/+/kind tallies.
        self.state.status = compare_hide_gap_nav_status(dir, n, ord, total, &counts, wrapped);
    }

    /// Expand the collapsed Equal run nearest the focused caret (menu / keyboard).
    fn expand_compare_hide_equal_at_caret(&mut self) {
        if !self.compare_on {
            self.state.status = "Compare off — start Compare to expand hidden equal lines".into();
            return;
        }
        if !self.state.settings.compare_hide_equal {
            self.state.status =
                "Hide Unchanged Lines is off — turn it on to collapse, then expand".into();
            return;
        }
        let left_pane = self.focused_pane == EditorPane::Primary || !self.dual_view;
        let tab = if left_pane {
            self.compare_left_tab
        } else {
            self.compare_right_tab
        };
        let Some(doc) = self.state.tabs.get(tab) else {
            return;
        };
        let line = doc.buffer.char_to_line(doc.buffer.caret());
        let line_count = doc.buffer.line_count().max(1);
        let (tags, revealed) = if left_pane {
            (&self.compare_left_tags, &self.compare_hide_revealed_left)
        } else {
            (&self.compare_right_tags, &self.compare_hide_revealed_right)
        };
        let visible = visible_lines_with_compare_hide(
            line_count,
            &doc.hidden_lines,
            true,
            true,
            tags,
            revealed,
            self.state.settings.compare_hide_equal_context_lines(),
        );
        let Some(gap) = crate::diff::nearest_compare_hide_gap(line, &visible) else {
            self.state.status = "Compare: no hidden equal run at caret".into();
            return;
        };
        if !self.expand_compare_hide_gap(gap, left_pane) {
            self.state.status = "Compare: no hidden equal run at caret".into();
        }
    }

    /// Re-collapse the expanded Equal run nearest the focused caret (menu / keyboard).
    fn collapse_compare_hide_equal_at_caret(&mut self) {
        if !self.compare_on {
            self.state.status =
                "Compare off — start Compare to collapse expanded equal lines".into();
            return;
        }
        if !self.state.settings.compare_hide_equal {
            self.state.status =
                "Hide Unchanged Lines is off — turn it on to collapse unchanged lines".into();
            return;
        }
        let left_pane = self.focused_pane == EditorPane::Primary || !self.dual_view;
        let tab = if left_pane {
            self.compare_left_tab
        } else {
            self.compare_right_tab
        };
        let Some(doc) = self.state.tabs.get(tab) else {
            return;
        };
        let line = doc.buffer.char_to_line(doc.buffer.caret());
        let gap = {
            let revealed = if left_pane {
                &self.compare_hide_revealed_left
            } else {
                &self.compare_hide_revealed_right
            };
            crate::diff::nearest_compare_revealed_run(line, revealed)
        };
        let Some(gap) = gap else {
            self.state.status = "Compare: no expanded equal run at caret".into();
            return;
        };
        if !self.collapse_compare_hide_gap(gap, left_pane) {
            self.state.status = "Compare: no expanded equal run at caret".into();
        }
    }

    /// Hide one previously expanded Equal run on the focused pane and its partners.
    fn collapse_compare_hide_gap(&mut self, gap: (usize, usize), left_pane: bool) -> bool {
        let n = if left_pane {
            crate::diff::collapse_compare_gap(&mut self.compare_hide_revealed_left, gap)
        } else {
            crate::diff::collapse_compare_gap(&mut self.compare_hide_revealed_right, gap)
        };
        if n == 0 {
            return false;
        }
        let partners = crate::diff::aligned_equal_partner_lines(
            &self.compare_left_tags,
            &self.compare_right_tags,
            gap,
            left_pane,
        );
        let n_other = if left_pane {
            crate::diff::collapse_compare_lines(&mut self.compare_hide_revealed_right, &partners)
        } else {
            crate::diff::collapse_compare_lines(&mut self.compare_hide_revealed_left, &partners)
        };
        let hide = compare_hide_opt(
            true,
            &self.compare_left_tags,
            &self.compare_right_tags,
            &self.compare_hide_revealed_left,
            &self.compare_hide_revealed_right,
            self.state.settings.compare_hide_equal_context_lines(),
        );
        let remain = hide.map(|(l, r)| l + r).unwrap_or(0);
        let both = if n_other > 0 { " both panes" } else { "" };
        let counts =
            compare_pair_counts_from_tags(&self.compare_left_tags, &self.compare_right_tags);
        self.state.status = compare_collapse_gap_status(
            n,
            both,
            counts.del,
            counts.ins,
            counts.hunk_n,
            &counts.kind_bit,
            remain,
        );
        true
    }

    /// Reveal every collapsed Equal run on both panes; hide-equal preference stays on.
    fn expand_all_compare_hide_equal(&mut self) {
        if !self.compare_on {
            self.state.status = "Compare off — start Compare to expand hidden equal lines".into();
            return;
        }
        if !self.state.settings.compare_hide_equal {
            self.state.status =
                "Hide Unchanged Lines is off — turn it on to collapse, then expand".into();
            return;
        }
        let n_left = crate::diff::reveal_all_compare_hidden(
            &mut self.compare_hide_revealed_left,
            &self.compare_left_tags,
            self.state.settings.compare_hide_equal_context_lines(),
        );
        let n_right = crate::diff::reveal_all_compare_hidden(
            &mut self.compare_hide_revealed_right,
            &self.compare_right_tags,
            self.state.settings.compare_hide_equal_context_lines(),
        );
        let n = n_left + n_right;
        self.state.status = if n == 0 {
            "Compare: no hidden equal lines".into()
        } else {
            let counts =
                compare_pair_counts_from_tags(&self.compare_left_tags, &self.compare_right_tags);
            compare_expand_all_unchanged_status(
                counts.del,
                counts.ins,
                counts.hunk_n,
                &counts.kind_bit,
                n,
            )
        };
    }

    /// Re-collapse click/menu-expanded Equal runs; hide-equal preference stays on.
    fn collapse_all_compare_hide_equal(&mut self) {
        if !self.compare_on {
            self.state.status =
                "Compare off — start Compare to collapse expanded equal lines".into();
            return;
        }
        if !self.state.settings.compare_hide_equal {
            self.state.status =
                "Hide Unchanged Lines is off — turn it on to collapse unchanged lines".into();
            return;
        }
        let n_left =
            crate::diff::collapse_all_compare_revealed(&mut self.compare_hide_revealed_left);
        let n_right =
            crate::diff::collapse_all_compare_revealed(&mut self.compare_hide_revealed_right);
        let n = n_left + n_right;
        let hide = compare_hide_opt(
            true,
            &self.compare_left_tags,
            &self.compare_right_tags,
            &self.compare_hide_revealed_left,
            &self.compare_hide_revealed_right,
            self.state.settings.compare_hide_equal_context_lines(),
        );
        let remain = hide.map(|(l, r)| l + r).unwrap_or(0);
        self.state.status = if n == 0 {
            if remain == 0 {
                "Compare: no expanded equal lines to collapse".into()
            } else {
                format!("Compare: equal lines already collapsed ({remain} hidden)")
            }
        } else {
            let counts =
                compare_pair_counts_from_tags(&self.compare_left_tags, &self.compare_right_tags);
            compare_collapse_all_unchanged_status(
                counts.del,
                counts.ins,
                counts.hunk_n,
                &counts.kind_bit,
                n,
                remain,
            )
        };
    }

    /// Bookmark every change-hunk start on both Compare panes (F2 / Shift+F2).
    fn bookmark_compare_differences(&mut self) {
        if !self.compare_on {
            self.state.status = "Compare off — start Compare to bookmark differences".into();
            return;
        }
        let left_starts = crate::diff::hunk_starts(&self.compare_left_tags);
        let right_starts = crate::diff::hunk_starts(&self.compare_right_tags);
        if left_starts.is_empty() && right_starts.is_empty() {
            self.state.status = "Compare: no differences to bookmark (identical)".into();
            return;
        }
        let left_tab = self.compare_left_tab;
        let right_tab = self.compare_right_tab;
        let mut added_l = 0usize;
        let mut added_r = 0usize;
        if let Some(doc) = self.state.tabs.get_mut(left_tab) {
            for &line in &left_starts {
                if doc.bookmarks.insert(line) {
                    added_l += 1;
                }
            }
        }
        if right_tab != left_tab {
            if let Some(doc) = self.state.tabs.get_mut(right_tab) {
                for &line in &right_starts {
                    if doc.bookmarks.insert(line) {
                        added_r += 1;
                    }
                }
            }
        }
        let counts =
            compare_pair_counts_from_tags(&self.compare_left_tags, &self.compare_right_tags);
        let added = added_l + added_r;
        self.state.status = compare_bookmark_differences_status(
            counts.del,
            counts.ins,
            left_starts.len(),
            right_starts.len(),
            counts.hunk_n,
            &counts.kind_bit,
            added,
        );
    }

    /// Clear bookmarks at each change-hunk start on both Compare panes.
    fn clear_compare_difference_bookmarks(&mut self) {
        if !self.compare_on {
            self.state.status = "Compare off — start Compare to clear difference bookmarks".into();
            return;
        }
        let left_starts = crate::diff::hunk_starts(&self.compare_left_tags);
        let right_starts = crate::diff::hunk_starts(&self.compare_right_tags);
        if left_starts.is_empty() && right_starts.is_empty() {
            self.state.status = "Compare: no difference bookmarks to clear (identical)".into();
            return;
        }
        let left_tab = self.compare_left_tab;
        let right_tab = self.compare_right_tab;
        let mut removed_l = 0usize;
        let mut removed_r = 0usize;
        if let Some(doc) = self.state.tabs.get_mut(left_tab) {
            for &line in &left_starts {
                if doc.bookmarks.remove(&line) {
                    removed_l += 1;
                }
            }
        }
        if right_tab != left_tab {
            if let Some(doc) = self.state.tabs.get_mut(right_tab) {
                for &line in &right_starts {
                    if doc.bookmarks.remove(&line) {
                        removed_r += 1;
                    }
                }
            }
        }
        let counts =
            compare_pair_counts_from_tags(&self.compare_left_tags, &self.compare_right_tags);
        let removed = removed_l + removed_r;
        self.state.status = compare_clear_difference_bookmarks_status(
            counts.del,
            counts.ins,
            left_starts.len(),
            right_starts.len(),
            counts.hunk_n,
            &counts.kind_bit,
            removed,
        );
    }

    /// Toggle hide-unchanged-lines for Compare; persist (no re-diff needed).
    fn toggle_compare_hide_equal(&mut self) {
        self.state.settings.compare_hide_equal = !self.state.settings.compare_hide_equal;
        self.state.settings.save();
        let hide_equal = self.state.settings.compare_hide_equal;
        if self.compare_on {
            self.refresh_compare_after_hide_equal_change();
        } else {
            if !hide_equal {
                self.compare_hide_revealed_left.clear();
                self.compare_hide_revealed_right.clear();
            }
            self.state.status = format!(
                "Hide unchanged lines: {}{}",
                if hide_equal { "on" } else { "off" },
                if hide_equal {
                    format!(
                        " (±{} context; applies when Compare is on)",
                        self.state.settings.compare_hide_equal_context_lines()
                    )
                } else {
                    String::new()
                }
            );
        }
    }

    /// Apply hide-unchanged after the setting already changed (View or Preferences).
    /// Clears ···N expansions when hiding turns off; parks first hunk while Compare is on.
    fn refresh_compare_after_hide_equal_change(&mut self) {
        let hide_equal = self.state.settings.compare_hide_equal;
        if !hide_equal {
            self.compare_hide_revealed_left.clear();
            self.compare_hide_revealed_right.clear();
        }
        if !self.compare_on {
            return;
        }
        let ignore = CompareIgnoreBits {
            ws: self.state.settings.compare_ignore_ws,
            case: self.state.settings.compare_ignore_case,
            blank: self.state.settings.compare_ignore_blank,
        };
        let left = self.compare_left_tab;
        let right = self.compare_right_tab;
        let lname = self
            .state
            .tabs
            .get(left)
            .map(|d| d.title.clone())
            .unwrap_or_else(|| "left".into());
        let rname = self
            .state
            .tabs
            .get(right)
            .map(|d| d.title.clone())
            .unwrap_or_else(|| "right".into());
        let hide = compare_hide_opt(
            hide_equal,
            &self.compare_left_tags,
            &self.compare_right_tags,
            &self.compare_hide_revealed_left,
            &self.compare_hide_revealed_right,
            self.state.settings.compare_hide_equal_context_lines(),
        );
        let counts =
            compare_pair_counts_from_tags(&self.compare_left_tags, &self.compare_right_tags);
        let hunk_n = counts.hunk_n;
        // Hide toggle can orphan the caret on a now-hidden Equal line — re-park like
        // Compare start / ignore re-diff / swap.
        if hunk_n > 0 {
            self.park_compare_hunk_ordinal(1);
            self.select_compare_hunk_on_pane(true, 1);
            self.select_compare_hunk_on_pane(false, 1);
        }
        let mut status = compare_pair_status(
            &lname,
            &rname,
            counts,
            ignore,
            CompareHideStatus {
                hidden: hide,
                context: self.state.settings.compare_hide_equal_context_lines(),
            },
            self.compare_sides_truncated(),
        );
        if hunk_n > 0 {
            let lr = self.compare_hunk_lr_label(1);
            let ordinal = self.compare_hunk_ordinal_bit(1, hunk_n);
            status.push_str(&compare_at_hunk_status_bit(&lr, &ordinal));
        }
        self.state.status = status;
    }

    /// Bump Preferences hide-equal context by ±1 (clamped 0..=10).
    fn adjust_compare_hide_equal_context(&mut self, delta: i8) {
        let prev = self.state.settings.compare_hide_equal_context_lines();
        let next = (prev as i32 + i32::from(delta)).clamp(0, 10) as usize;
        self.set_compare_hide_equal_context(next);
    }

    /// Set Preferences hide-equal context (clamped 0..=10); clear ···N expansions.
    /// While Compare + Hide Unchanged is on, parks both panes on the first change hunk.
    fn set_compare_hide_equal_context(&mut self, next: usize) {
        let prev = self.state.settings.compare_hide_equal_context_lines();
        let next = next.clamp(0, 10);
        if next == prev {
            self.state.status = format!("Hide-equal context already ±{prev}");
            return;
        }
        self.state.settings.compare_hide_equal_context = next as u8;
        self.state.settings.save();
        let hide_equal = self.state.settings.compare_hide_equal;
        if self.compare_on && hide_equal {
            self.compare_hide_revealed_left.clear();
            self.compare_hide_revealed_right.clear();
        }
        let ctx = next;
        let ignore = CompareIgnoreBits {
            ws: self.state.settings.compare_ignore_ws,
            case: self.state.settings.compare_ignore_case,
            blank: self.state.settings.compare_ignore_blank,
        };
        if self.compare_on {
            let left = self.compare_left_tab;
            let right = self.compare_right_tab;
            let lname = self
                .state
                .tabs
                .get(left)
                .map(|d| d.title.clone())
                .unwrap_or_else(|| "left".into());
            let rname = self
                .state
                .tabs
                .get(right)
                .map(|d| d.title.clone())
                .unwrap_or_else(|| "right".into());
            let hide = compare_hide_opt(
                hide_equal,
                &self.compare_left_tags,
                &self.compare_right_tags,
                &self.compare_hide_revealed_left,
                &self.compare_hide_revealed_right,
                ctx,
            );
            let counts =
                compare_pair_counts_from_tags(&self.compare_left_tags, &self.compare_right_tags);
            let hunk_n = counts.hunk_n;
            // Context change can orphan the caret on a now-hidden Equal line — re-park like
            // hide-equal toggle / Compare start / ignore re-diff / swap.
            if hide_equal && hunk_n > 0 {
                self.park_compare_hunk_ordinal(1);
                self.select_compare_hunk_on_pane(true, 1);
                self.select_compare_hunk_on_pane(false, 1);
            }
            let mut status = compare_pair_status(
                &lname,
                &rname,
                counts,
                ignore,
                CompareHideStatus {
                    hidden: hide,
                    context: ctx,
                },
                self.compare_sides_truncated(),
            );
            if hide_equal && hunk_n > 0 {
                let lr = self.compare_hunk_lr_label(1);
                let ordinal = self.compare_hunk_ordinal_bit(1, hunk_n);
                status.push_str(&compare_at_hunk_status_bit(&lr, &ordinal));
            }
            self.state.status = format!("Hide-equal context ±{ctx} — {status}");
        } else {
            self.state.status = format!(
                "Hide-equal context ±{ctx} (applies when Hide Unchanged Lines is on during Compare)"
            );
        }
    }

    /// Lines used for Compare LCS / unified diff (capped at [`crate::diff::MAX_COMPARE_LINES`]).
    fn tab_compare_lines(&self, tab: usize) -> Vec<String> {
        self.state
            .tabs
            .get(tab)
            .map(|d| {
                let n = d.buffer.line_count().min(crate::diff::MAX_COMPARE_LINES);
                (0..n)
                    .map(|i| d.buffer.line(i).trim_end_matches(['\n', '\r']).to_string())
                    .collect()
            })
            .unwrap_or_default()
    }

    /// True when either Compare side has more lines than the LCS cap (tail uncoloured).
    fn compare_sides_truncated(&self) -> bool {
        let max = crate::diff::MAX_COMPARE_LINES;
        let left = self
            .state
            .tabs
            .get(self.compare_left_tab)
            .map(|d| d.buffer.line_count())
            .unwrap_or(0);
        let right = self
            .state
            .tabs
            .get(self.compare_right_tab)
            .map(|d| d.buffer.line_count())
            .unwrap_or(0);
        left > max || right > max
    }

    fn compare_side_name(title: &str) -> String {
        title.replace(['\n', '\r'], " ")
    }

    /// Unified diff text for the current Compare pair.
    fn compare_unified_diff_text(
        &mut self,
    ) -> Option<(String, String, String, usize, usize, usize, String)> {
        if !self.compare_on {
            return None;
        }
        let left = self.compare_left_tab;
        let right = self.compare_right_tab;
        let left_lines = self.tab_compare_lines(left);
        let right_lines = self.tab_compare_lines(right);
        if left_lines.len() != self.compare_left_tags.len()
            || right_lines.len() != self.compare_right_tags.len()
        {
            if let Some((lt, rt, _, _)) = self.compute_compare_tags(left, right) {
                self.compare_left_tags = lt;
                self.compare_right_tags = rt;
            } else {
                return None;
            }
        }
        let lname = self
            .state
            .tabs
            .get(left)
            .map(|d| Self::compare_side_name(&d.title))
            .unwrap_or_else(|| "left".into());
        let rname = self
            .state
            .tabs
            .get(right)
            .map(|d| Self::compare_side_name(&d.title))
            .unwrap_or_else(|| "right".into());
        let left_refs: Vec<&str> = left_lines.iter().map(String::as_str).collect();
        let right_refs: Vec<&str> = right_lines.iter().map(String::as_str).collect();
        let text = crate::diff::unified_diff(
            &left_refs,
            &right_refs,
            &lname,
            &rname,
            &self.compare_left_tags,
            &self.compare_right_tags,
        )?;
        let (del, ins) =
            crate::diff::count_changes(&self.compare_left_tags, &self.compare_right_tags);
        let hunk_n =
            crate::diff::compare_summary_hunks(&self.compare_left_tags, &self.compare_right_tags)
                .map(|h| h.len())
                .unwrap_or(0);
        let kind_bit =
            crate::diff::compare_kind_tally_bit(&self.compare_left_tags, &self.compare_right_tags);
        Some((text, lname, rname, del, ins, hunk_n, kind_bit))
    }

    /// Clipboard: unified diff of the current Compare pair.
